insert into public.qcm_bank
  (bank_id, otr_number, module, chapter, context, star, corrected, stem, options, justification, sources)
values
(2624, 7, 'Traumatologie', 'Complication de l’immobilité et décubitus', 'Interne à Grenoble, vous recevez Madame J. 34 ans, skieuse amateur, amenée par les pompiers pour douleurs et impotence fonctionnelle totale suite à une chute sur les pistes. La patiente décrit « un déboÎtement de sa jambe droite qui se serait remise toute seule ». L''EVA de la douleur est cotée à 8110, le genou semble tuméfié sans trouble de la statique.', false, true, 'Concernant le Ginding test (ou test d'' Apley), quelles sont les propositions vraies ?', '[{"l":"A","t":"Réalisée en décubitus ventral","c":true},{"l":"B","t":"Le genou est fléchi à 90°","c":true},{"l":"C","t":"Nécessite des mouvements de rotations de la jambe","c":true},{"l":"D","t":"Est positif en cas de douleur déclenchée à la manœuvre","c":true},{"l":"E","t":"Est positif en cas de ressaut","c":false}]'::jsonb, NULL, '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2625, 36, 'Traumatologie', 'Traumatismes ligamentaires du genou', 'Interne à Grenoble, vous recevez Madame J. 34 ans, skieuse amateur, amenée par les pompiers pour douleurs et impotence fonctionnelle totale suite à une chute sur les pistes. La patiente décrit « un déboÎtement de sa jambe droite qui se serait remise toute seule ». L''EVA de la douleur est cotée à 8110, le genou semble tuméfié sans trouble de la statique.', false, true, 'Quels sont les principes du traitement ?', '[{"l":"A","t":"Suture méniscale","c":true},{"l":"B","t":"Méniscectomie interne","c":false},{"l":"C","t":"Greffe méniscale type DIDT","c":false},{"l":"D","t":"Intervention sous arthroscopie","c":true},{"l":"E","t":"Absence d''appui pendant 6 semaines","c":false}]'::jsonb, 'Conseil du spécialiste : ATIENTION en cas de méniscectomie, toujours mentionner le caractére « économique » de l''intervention. Le minimum sera retiré pour permettre le meilleur pronostic possible à long terme.', '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2626, 1, 'Chirurgie pédiatrique', 'Généralités sur les fractures de l’enfant et les traumatismes du cartilage de croissance', 'Interne de pédiatrie en région parisienne, vous recevez Je petit Victor, 8 mois, accompagné de ses parents. Ceux-ci ont trouvé beaucoup d''informations critiques à propos des vaccins, des prescriptions médicales et du lait artificiel. Ils ont donc décidé que leur enfant ne serait nourri qu''au sein et ne prendrait pas de médicaments «dangereux et inutiles». Les parents se sont finalement affolés car la courbe staturo-pondéra/e était anormale. Ce jour, il pèse 6 kg (-2DS) et mesure 65 cm (-1 DS). En consultant son carnet de santé vous apprenez que ce nourrisson est né à terme avec une taille et un poids de naissance normal, que ses vaccins ne sont pas à jour. Il n''a pas présenté de problèmes de santé particuliers depuis sa sortie de la maternité. Après un examen clinique soigné, vous évoquez la possibilité d''un rachitisme carentiel.', false, true, 'Quels éléments cliniques ont pu vous orienter ?', '[{"l":"A","t":"Un retard de croissance pondéral","c":true},{"l":"B","t":"Un genu varum","c":true},{"l":"C","t":"Une fermeture précoce des fontanelles","c":false},{"l":"D","t":"Un retard à l''apparition des dents","c":true},{"l":"E","t":"Une hypotonie","c":true}]'::jsonb, 'Conseil du spécialiste : Signes cliniques du rachitime : bourrelets des poignets et des chevilles, genu varum ou valgum, coxa vara, pieds plats, cyphose, «chapelet costal», craniotabès, retard de fermeture des fontanelles, retard de dentition, hypo-tonie musculaire, mètéorisme abdominal, hyperlaxitè ligamentaire, retard au maintien de la tête, à la position assise et à la marche...', '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2627, 1, 'Chirurgie pédiatrique', 'Généralités sur les fractures de l’enfant et les traumatismes du cartilage de croissance', 'Interne de pédiatrie en région parisienne, vous recevez Je petit Victor, 8 mois, accompagné de ses parents. Ceux-ci ont trouvé beaucoup d''informations critiques à propos des vaccins, des prescriptions médicales et du lait artificiel. Ils ont donc décidé que leur enfant ne serait nourri qu''au sein et ne prendrait pas de médicaments «dangereux et inutiles». Les parents se sont finalement affolés car la courbe staturo-pondéra/e était anormale. Ce jour, il pèse 6 kg (-2DS) et mesure 65 cm (-1 DS). En consultant son carnet de santé vous apprenez que ce nourrisson est né à terme avec une taille et un poids de naissance normal, que ses vaccins ne sont pas à jour. Il n''a pas présenté de problèmes de santé particuliers depuis sa sortie de la maternité. Après un examen clinique soigné, vous évoquez la possibilité d''un rachitisme carentiel.', false, true, 'À propos du traitement préventif de cette pathologie, quelles sont les propositions vraies ?', '[{"l":"A","t":"Vitamine D uniquement en cas de facteur de risque de carence (peau noire, exposition solaire faible)","c":false},{"l":"B","t":"Vitamine D une fois par jour pendant la première année de vie en cas de nutrition par lait artificiel","c":true},{"l":"C","t":"Vitamine D une fois par jour pendant la première année de vie en cas d''allaitement","c":true},{"l":"D","t":"Une exposition solaire est recommandée","c":false},{"l":"E","t":"Il existe un risque d''hypocalcémie en cas de surdosage","c":false}]'::jsonb, NULL, '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2628, 1, 'Chirurgie pédiatrique', 'Généralités sur les fractures de l’enfant et les traumatismes du cartilage de croissance', 'Interne de pédiatrie en région parisienne, vous recevez Je petit Victor, 8 mois, accompagné de ses parents. Ceux-ci ont trouvé beaucoup d''informations critiques à propos des vaccins, des prescriptions médicales et du lait artificiel. Ils ont donc décidé que leur enfant ne serait nourri qu''au sein et ne prendrait pas de médicaments «dangereux et inutiles». Les parents se sont finalement affolés car la courbe staturo-pondéra/e était anormale. Ce jour, il pèse 6 kg (-2DS) et mesure 65 cm (-1 DS). En consultant son carnet de santé vous apprenez que ce nourrisson est né à terme avec une taille et un poids de naissance normal, que ses vaccins ne sont pas à jour. Il n''a pas présenté de problèmes de santé particuliers depuis sa sortie de la maternité. Après un examen clinique soigné, vous évoquez la possibilité d''un rachitisme carentiel.', false, true, 'La mère vous parle d''arrêter l''allaitement. Quels sont les principes de la nutrition d''un nourrisson de 8 mois que vous lui donnez ?', '[{"l":"A","t":"Lait artificiel type « préparation de suite »jusqu''à 1 an.","c":true},{"l":"B","t":"Au moins 500 ml/j","c":true},{"l":"C","t":"1 cuillère de lait en poudre dans 30 ml d''eau","c":true},{"l":"D","t":"Diversification progressive à partir de 1an","c":false},{"l":"E","t":"Vitamine K jusqu''à 2 ans","c":false}]'::jsonb, NULL, '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2629, 1, 'Chirurgie pédiatrique', 'Généralités sur les fractures de l’enfant et les traumatismes du cartilage de croissance', 'Interne de pédiatrie en région parisienne, vous recevez Je petit Victor, 8 mois, accompagné de ses parents. Ceux-ci ont trouvé beaucoup d''informations critiques à propos des vaccins, des prescriptions médicales et du lait artificiel. Ils ont donc décidé que leur enfant ne serait nourri qu''au sein et ne prendrait pas de médicaments «dangereux et inutiles». Les parents se sont finalement affolés car la courbe staturo-pondéra/e était anormale. Ce jour, il pèse 6 kg (-2DS) et mesure 65 cm (-1 DS). En consultant son carnet de santé vous apprenez que ce nourrisson est né à terme avec une taille et un poids de naissance normal, que ses vaccins ne sont pas à jour. Il n''a pas présenté de problèmes de santé particuliers depuis sa sortie de la maternité. Après un examen clinique soigné, vous évoquez la possibilité d''un rachitisme carentiel.', false, true, 'Quels vaccins aurait dû avoir cet enfant ?', '[{"l":"A","t":"1 dose de BCG","c":true},{"l":"B","t":"2 doses de vaccin contre l''hépatite B en cas de facteur de risque","c":false},{"l":"C","t":"1 dose de ROR","c":false},{"l":"D","t":"2 doses de DTCaP","c":true},{"l":"E","t":"1 dose de vaccin contre le méningocoque C","c":false}]'::jsonb, NULL, '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2630, 1, 'Chirurgie pédiatrique', 'Généralités sur les fractures de l’enfant et les traumatismes du cartilage de croissance', 'Interne de pédiatrie en région parisienne, vous recevez Je petit Victor, 8 mois, accompagné de ses parents. Ceux-ci ont trouvé beaucoup d''informations critiques à propos des vaccins, des prescriptions médicales et du lait artificiel. Ils ont donc décidé que leur enfant ne serait nourri qu''au sein et ne prendrait pas de médicaments «dangereux et inutiles». Les parents se sont finalement affolés car la courbe staturo-pondéra/e était anormale. Ce jour, il pèse 6 kg (-2DS) et mesure 65 cm (-1 DS). En consultant son carnet de santé vous apprenez que ce nourrisson est né à terme avec une taille et un poids de naissance normal, que ses vaccins ne sont pas à jour. Il n''a pas présenté de problèmes de santé particuliers depuis sa sortie de la maternité. Après un examen clinique soigné, vous évoquez la possibilité d''un rachitisme carentiel.', false, true, 'Vous retrouvez cet enfant 1 mois plus tard aux urgences pédiatriques. Sa mère, qui l''accompagne, vous explique qu''il est tombé de sa chaise haute : « c''est la deuxième fois cette semaine, mais là, son comportement est étrange et il n''a même pas pleuré. Je crois qu''il s''est cassé quelque chose cette fois-ci ». Le nourrisson est somnolent et hypotonique, son périmètre crânien est augmenté. Vous notez de multiples hématomes musculaires. Sa jambe droite est déformée. Vous évoquez une maltraitance. Quels éléments vous font craindre une hypertension intracrânienne ?', '[{"l":"A","t":"Un œdème papillaire unilatéral","c":false},{"l":"B","t":"Un trouble de la vigilance","c":true},{"l":"C","t":"Des vomissements en jet","c":true},{"l":"D","t":"Une grande pâleur","c":true},{"l":"E","t":"Un plafonnement du regard","c":true}]'::jsonb, NULL, '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2631, 1, 'Chirurgie pédiatrique', 'Généralités sur les fractures de l’enfant et les traumatismes du cartilage de croissance', 'Interne de pédiatrie en région parisienne, vous recevez Je petit Victor, 8 mois, accompagné de ses parents. Ceux-ci ont trouvé beaucoup d''informations critiques à propos des vaccins, des prescriptions médicales et du lait artificiel. Ils ont donc décidé que leur enfant ne serait nourri qu''au sein et ne prendrait pas de médicaments «dangereux et inutiles». Les parents se sont finalement affolés car la courbe staturo-pondéra/e était anormale. Ce jour, il pèse 6 kg (-2DS) et mesure 65 cm (-1 DS). En consultant son carnet de santé vous apprenez que ce nourrisson est né à terme avec une taille et un poids de naissance normal, que ses vaccins ne sont pas à jour. Il n''a pas présenté de problèmes de santé particuliers depuis sa sortie de la maternité. Après un examen clinique soigné, vous évoquez la possibilité d''un rachitisme carentiel.', false, true, 'Quel(s) pathologie(s) aurai(en)t pu être à l''origine des hématomes multiples chez ce nourrisson ?', '[{"l":"A","t":"Une carence en vitamine K","c":true},{"l":"B","t":"Une maladie de Willebrand type 1","c":false},{"l":"C","t":"Une maladie cœliaque","c":true},{"l":"D","t":"Une hémophilie A","c":true},{"l":"E","t":"Une leucémie","c":true}]'::jsonb, 'Conseil du spécialiste : Piège, dans la maladie de Willebrand de type 1 (la plus fréquente), il s''agit d''un trouble de l''agrègation et donc on aura des ecchymoses plutôt que des hématomes', '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2632, 1, 'Chirurgie pédiatrique', 'Généralités sur les fractures de l’enfant et les traumatismes du cartilage de croissance', 'Interne de pédiatrie en région parisienne, vous recevez Je petit Victor, 8 mois, accompagné de ses parents. Ceux-ci ont trouvé beaucoup d''informations critiques à propos des vaccins, des prescriptions médicales et du lait artificiel. Ils ont donc décidé que leur enfant ne serait nourri qu''au sein et ne prendrait pas de médicaments «dangereux et inutiles». Les parents se sont finalement affolés car la courbe staturo-pondéra/e était anormale. Ce jour, il pèse 6 kg (-2DS) et mesure 65 cm (-1 DS). En consultant son carnet de santé vous apprenez que ce nourrisson est né à terme avec une taille et un poids de naissance normal, que ses vaccins ne sont pas à jour. Il n''a pas présenté de problèmes de santé particuliers depuis sa sortie de la maternité. Après un examen clinique soigné, vous évoquez la possibilité d''un rachitisme carentiel.', false, true, 'Quels examens complémentaires demandez-vous ?', '[{"l":"A","t":"Radiographies corps entier","c":true},{"l":"B","t":"Scanner cérébral","c":true},{"l":"C","t":"Body Scanner","c":false},{"l":"D","t":"Bilan d''hémostase","c":true},{"l":"E","t":"Échographie abdominale","c":true}]'::jsonb, NULL, '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2633, 1, 'Chirurgie pédiatrique', 'Généralités sur les fractures de l’enfant et les traumatismes du cartilage de croissance', 'Interne de pédiatrie en région parisienne, vous recevez Je petit Victor, 8 mois, accompagné de ses parents. Ceux-ci ont trouvé beaucoup d''informations critiques à propos des vaccins, des prescriptions médicales et du lait artificiel. Ils ont donc décidé que leur enfant ne serait nourri qu''au sein et ne prendrait pas de médicaments «dangereux et inutiles». Les parents se sont finalement affolés car la courbe staturo-pondéra/e était anormale. Ce jour, il pèse 6 kg (-2DS) et mesure 65 cm (-1 DS). En consultant son carnet de santé vous apprenez que ce nourrisson est né à terme avec une taille et un poids de naissance normal, que ses vaccins ne sont pas à jour. Il n''a pas présenté de problèmes de santé particuliers depuis sa sortie de la maternité. Après un examen clinique soigné, vous évoquez la possibilité d''un rachitisme carentiel.', false, true, 'Quelles anomalies radiologiques vous font évoquer un syndrome de Silverman chez cet enfant ?', '[{"l":"A","t":"Appositions périostées en bec d''oiseau","c":false},{"l":"B","t":"Fracture diaphysaire du membre inférieur","c":true},{"l":"C","t":"Arrachement métaphysaire","c":true},{"l":"D","t":"Fractures costales","c":true},{"l":"E","t":"Hématome sous-périosté","c":true}]'::jsonb, NULL, '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2634, 1, 'Chirurgie pédiatrique', 'Généralités sur les fractures de l’enfant et les traumatismes du cartilage de croissance', 'Interne de pédiatrie en région parisienne, vous recevez Je petit Victor, 8 mois, accompagné de ses parents. Ceux-ci ont trouvé beaucoup d''informations critiques à propos des vaccins, des prescriptions médicales et du lait artificiel. Ils ont donc décidé que leur enfant ne serait nourri qu''au sein et ne prendrait pas de médicaments «dangereux et inutiles». Les parents se sont finalement affolés car la courbe staturo-pondéra/e était anormale. Ce jour, il pèse 6 kg (-2DS) et mesure 65 cm (-1 DS). En consultant son carnet de santé vous apprenez que ce nourrisson est né à terme avec une taille et un poids de naissance normal, que ses vaccins ne sont pas à jour. Il n''a pas présenté de problèmes de santé particuliers depuis sa sortie de la maternité. Après un examen clinique soigné, vous évoquez la possibilité d''un rachitisme carentiel.', false, true, 'Quelle est votre attitude concernant la protection de l''enfant?', '[{"l":"A","t":"Hospitalisation par ordonnance de placement provisoire avec l''accord des parents","c":false},{"l":"B","t":"Signalement judiciaire au procureur de la république","c":true},{"l":"C","t":"Rédaction d''un certificat médical mentionnant la suspicion de maltraitance","c":false},{"l":"D","t":"Rédaction d''un certificat médical décrivant les lésions et leur origine supposée.","c":false},{"l":"E","t":"Absence de signalement en cas d''accord des parents pour l''hospitalisation","c":false}]'::jsonb, 'Conseil du spécialiste : Attention , dans le CR, ne doivent pas être mentionnées la notion de maltraitance ou l''origne supposée des lésions.', '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2635, 1, 'Chirurgie pédiatrique', 'Généralités sur les fractures de l’enfant et les traumatismes du cartilage de croissance', 'Interne de pédiatrie en région parisienne, vous recevez Je petit Victor, 8 mois, accompagné de ses parents. Ceux-ci ont trouvé beaucoup d''informations critiques à propos des vaccins, des prescriptions médicales et du lait artificiel. Ils ont donc décidé que leur enfant ne serait nourri qu''au sein et ne prendrait pas de médicaments «dangereux et inutiles». Les parents se sont finalement affolés car la courbe staturo-pondéra/e était anormale. Ce jour, il pèse 6 kg (-2DS) et mesure 65 cm (-1 DS). En consultant son carnet de santé vous apprenez que ce nourrisson est né à terme avec une taille et un poids de naissance normal, que ses vaccins ne sont pas à jour. Il n''a pas présenté de problèmes de santé particuliers depuis sa sortie de la maternité. Après un examen clinique soigné, vous évoquez la possibilité d''un rachitisme carentiel.', false, true, 'Après sa prise en charge pluri-disciplinaire d''une fracture de la diaphyse fémorale gauche et d''un hématome sous-durai, le petit Victor va beaucoup mieux. Il est ensuite placé dans une famille d''accueil. Vous êtes amené à le revoir alors qu''il a maintenant 6 ans, pour boiterie. Vous remarquez qu''il dévie son centre de gravité dans l''axe de sa jambe gauche à la marche. Quels diagnostics évoquez-vous ?', '[{"l":"A","t":"Inégalité de longueur des membres","c":false},{"l":"B","t":"Synovite aiguë transitoire","c":true},{"l":"C","t":"Arthrite septique coxo-fémorale","c":true},{"l":"D","t":"Ostéochondrite primitive de hanche","c":true},{"l":"E","t":"Tumeur fémorale","c":false}]'::jsonb, 'Conseil du spécialiste : Boiterie de Trendelenburg =pathologie de la hanche.', '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2636, 11, 'Chirurgie pédiatrique', 'Boiterie chez l’enfant', 'Interne de pédiatrie en région parisienne, vous recevez Je petit Victor, 8 mois, accompagné de ses parents. Ceux-ci ont trouvé beaucoup d''informations critiques à propos des vaccins, des prescriptions médicales et du lait artificiel. Ils ont donc décidé que leur enfant ne serait nourri qu''au sein et ne prendrait pas de médicaments «dangereux et inutiles». Les parents se sont finalement affolés car la courbe staturo-pondéra/e était anormale. Ce jour, il pèse 6 kg (-2DS) et mesure 65 cm (-1 DS). En consultant son carnet de santé vous apprenez que ce nourrisson est né à terme avec une taille et un poids de naissance normal, que ses vaccins ne sont pas à jour. Il n''a pas présenté de problèmes de santé particuliers depuis sa sortie de la maternité. Après un examen clinique soigné, vous évoquez la possibilité d''un rachitisme carentiel.', false, true, 'En l''interrogeant vous retrouvez la notion de douleur inguinale gauche d''apparition plutôt brutale. Il n''y a pas de fièvre et aucun signe d''AEG. La douleur est d''horaire mécanique, il y a une limitation à l''abduction. Quel(s) examen(s) complémentaires prescrivez-vous ?', '[{"l":"A","t":"NFS","c":true},{"l":"B","t":"CRP","c":true},{"l":"C","t":"Radiographie du bassin","c":true},{"l":"D","t":"Échographie des hanches","c":true},{"l":"E","t":"Scintigraphie osseuse","c":false}]'::jsonb, NULL, '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2637, 11, 'Chirurgie pédiatrique', 'Boiterie chez l’enfant', 'Interne de pédiatrie en région parisienne, vous recevez Je petit Victor, 8 mois, accompagné de ses parents. Ceux-ci ont trouvé beaucoup d''informations critiques à propos des vaccins, des prescriptions médicales et du lait artificiel. Ils ont donc décidé que leur enfant ne serait nourri qu''au sein et ne prendrait pas de médicaments «dangereux et inutiles». Les parents se sont finalement affolés car la courbe staturo-pondéra/e était anormale. Ce jour, il pèse 6 kg (-2DS) et mesure 65 cm (-1 DS). En consultant son carnet de santé vous apprenez que ce nourrisson est né à terme avec une taille et un poids de naissance normal, que ses vaccins ne sont pas à jour. Il n''a pas présenté de problèmes de santé particuliers depuis sa sortie de la maternité. Après un examen clinique soigné, vous évoquez la possibilité d''un rachitisme carentiel.', false, true, 'Votre bilan revient normal. Quel est votre prise en charge?', '[{"l":"A","t":"Repos au lit","c":true},{"l":"B","t":"Traction axiale","c":false},{"l":"C","t":"Traitement antalgique par AINS","c":true},{"l":"D","t":"Radiographie de contrôle dans 1 à 2 mois","c":true},{"l":"E","t":"Dispense de sport courte","c":true}]'::jsonb, NULL, '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2638, 11, 'Chirurgie pédiatrique', 'Boiterie chez l’enfant', 'Interne de pédiatrie en région parisienne, vous recevez Je petit Victor, 8 mois, accompagné de ses parents. Ceux-ci ont trouvé beaucoup d''informations critiques à propos des vaccins, des prescriptions médicales et du lait artificiel. Ils ont donc décidé que leur enfant ne serait nourri qu''au sein et ne prendrait pas de médicaments «dangereux et inutiles». Les parents se sont finalement affolés car la courbe staturo-pondéra/e était anormale. Ce jour, il pèse 6 kg (-2DS) et mesure 65 cm (-1 DS). En consultant son carnet de santé vous apprenez que ce nourrisson est né à terme avec une taille et un poids de naissance normal, que ses vaccins ne sont pas à jour. Il n''a pas présenté de problèmes de santé particuliers depuis sa sortie de la maternité. Après un examen clinique soigné, vous évoquez la possibilité d''un rachitisme carentiel.', false, true, 'Les douleurs persistent, quel examen permettrait d''éliminer le diagnostic d''ostéochondrite primitive ?', '[{"l":"A","t":"IRM de hanche avec injection de gadolinium","c":false},{"l":"B","t":"PET scanner des membres inférieurs","c":false},{"l":"C","t":"Scanner des membres inférieurs avec injection de produit de contraste","c":false},{"l":"D","t":"Scintigraphie osseuse","c":true},{"l":"E","t":"Ponction articulaire avec étude biochimique et cytologique","c":false}]'::jsonb, NULL, '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2639, 11, 'Chirurgie pédiatrique', 'Boiterie chez l’enfant', 'Interne de pédiatrie en région parisienne, vous recevez Je petit Victor, 8 mois, accompagné de ses parents. Ceux-ci ont trouvé beaucoup d''informations critiques à propos des vaccins, des prescriptions médicales et du lait artificiel. Ils ont donc décidé que leur enfant ne serait nourri qu''au sein et ne prendrait pas de médicaments «dangereux et inutiles». Les parents se sont finalement affolés car la courbe staturo-pondéra/e était anormale. Ce jour, il pèse 6 kg (-2DS) et mesure 65 cm (-1 DS). En consultant son carnet de santé vous apprenez que ce nourrisson est né à terme avec une taille et un poids de naissance normal, que ses vaccins ne sont pas à jour. Il n''a pas présenté de problèmes de santé particuliers depuis sa sortie de la maternité. Après un examen clinique soigné, vous évoquez la possibilité d''un rachitisme carentiel.', false, true, 'Qu''en attendez-vous si le diagnostic d''ostéochondrite se confirme ?', '[{"l":"A","t":"Hypofixation localisée","c":true},{"l":"B","t":"Lésion en coup d''ongle","c":false},{"l":"C","t":"Image en coquille d''oeuf","c":false},{"l":"D","t":"Ligne de Klein anormale","c":false},{"l":"E","t":"Liquide articulaire inflammatoire","c":false}]'::jsonb, NULL, '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2640, 15, 'Traumatologie', 'Traumatismes du poignet : fracture du poignet ; fracture des os du carpe', 'Mademoiselle E., 36 ans, consulte aux urgences pour douleurs et déformation du poignet gauche suite à une chute sur son lieu de travail. Elle aurait trébuché car « ses nouveaux escarpins sont bien trop hauts ». Cette secrétaire sans enfants n''a pas d''antécédent particulier. Vous réalisez les radios suivantes : 0'')', false, true, 'Vous suspectez cliniquement une fracture du scaphoïde associée :', '[{"l":"A","t":"Cette fracture est visible sur la radiographie","c":false},{"l":"B","t":"Vous suspectez une fracture du scaphoïde devant une douleur à la palpation du deuxième rayon","c":false},{"l":"C","t":"Vous suspectez une fracture du scaphoïde devant une douleur à la palpation de la tabatière anatomique.","c":true},{"l":"D","t":"Cette fracture peut être explorée par un scanner du poignet","c":true},{"l":"E","t":"Une fracture du scaphoïde ne modifie pas la prise en charge","c":false}]'::jsonb, 'Conseil du spécialiste : Les fractures du scaphoïde sont difficile à diagnostiquer sur une radio, un scanner est souvent utile pour bien définir la localisation de la fracture qui modifie le diagnostic (ostéonécrose avasculaire).', '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2641, 15, 'Traumatologie', 'Traumatismes du poignet : fracture du poignet ; fracture des os du carpe', 'Mademoiselle E., 36 ans, consulte aux urgences pour douleurs et déformation du poignet gauche suite à une chute sur son lieu de travail. Elle aurait trébuché car « ses nouveaux escarpins sont bien trop hauts ». Cette secrétaire sans enfants n''a pas d''antécédent particulier. Vous réalisez les radios suivantes : 0'')', false, true, 'OA La patiente est très algique, vous décidez de débuter une titration morphinique IV. Quelles propositions sont vraies?', '[{"l":"A","t":"La dose de départ que vous délivrez est de 1 mg/kg","c":false},{"l":"B","t":"Vous réévaluez la douleur 5 min après la première prise","c":true},{"l":"C","t":"Vous délivrez une interdose dès que la douleur est > 30/100","c":true},{"l":"D","t":"Cette interdose correspond à 1/6 de la dose initiale","c":false},{"l":"E","t":"1 mg IV =3 mg per os","c":true}]'::jsonb, 'Conseil du spécialiste : Dose initiale= 0,05 mg/kg (environ 3 mg) en IV. Bolus de 2-3 mg tant que EVA > 30/100. Attention, avis spécialisé si dose cumulée> 20 mg.', '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2642, 35, 'Traumatologie', 'Syndrome du canal carpien', 'Mademoiselle E., 36 ans, consulte aux urgences pour douleurs et déformation du poignet gauche suite à une chute sur son lieu de travail. Elle aurait trébuché car « ses nouveaux escarpins sont bien trop hauts ». Cette secrétaire sans enfants n''a pas d''antécédent particulier. Vous réalisez les radios suivantes : 0'')', false, true, 'À propos des complications de cette fracture du poignet :', '[{"l":"A","t":"Vous recherchez une lésion du nerf médian par le testing de la pince pouce-V.","c":true},{"l":"B","t":"Vous recherchez une lésion vasculaire par le test de Phalen et la palpation des pouls périphériques.","c":false},{"l":"C","t":"Vous suspectez une lésion intra-articulaire par l''augmentation de la douleur à la mobilisation passive","c":false},{"l":"D","t":"Une lésion vasculo-nerveuse est rare en cas de déplacement faible de la fracture","c":true},{"l":"E","t":"Le testing nerveux peut être fait au bloc sous anesthésie générale par neurostimulation oc","c":false}]'::jsonb, 'Conseil du spécialiste : Ne pas confondre avec le test d''Allen visant à vérifier la suppléance de l''artére ulnaire. Le testing doit être fait avant l''opération afin d''informer la patiente en cas d''éventuelles lésions. 1O. Un syndrome peu connu des externes, tout est dans la question.', '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2643, 3, 'Traumatologie', 'Principe de base en médecine physique et réadaptation', 'Mademoiselle E., 36 ans, consulte aux urgences pour douleurs et déformation du poignet gauche suite à une chute sur son lieu de travail. Elle aurait trébuché car « ses nouveaux escarpins sont bien trop hauts ». Cette secrétaire sans enfants n''a pas d''antécédent particulier. Vous réalisez les radios suivantes : 0'')', false, true, 'Quel est le traitement de cette fracture ?', '[{"l":"A","t":"Réduction au bloc sous contrôle par radiographies du poignet répétées","c":false},{"l":"B","t":"Ostéosynthèse à foyer ouvert","c":true},{"l":"C","t":"Traitement orthopédique par plâtre brachio-antébrachio-palmaire","c":false},{"l":"D","t":"La kinésithérapie ne doit pas être débutée avant consolidation complète de la fracture","c":false},{"l":"E","t":"La méthode d''immobilisation n''est pas consensuelle","c":true}]'::jsonb, NULL, '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2644, 8, 'Traumatologie', 'Généralités sur les fractures de l’adulte', 'Mademoiselle E., 36 ans, consulte aux urgences pour douleurs et déformation du poignet gauche suite à une chute sur son lieu de travail. Elle aurait trébuché car « ses nouveaux escarpins sont bien trop hauts ». Cette secrétaire sans enfants n''a pas d''antécédent particulier. Vous réalisez les radios suivantes : 0'')', false, true, 'Qu''attendez-vous du bilan radiologique à + J7 ?', '[{"l":"A","t":"Un index radio-ulnaire normalement négatif ou nul","c":true},{"l":"B","t":"La présence d''appositions périostées","c":false},{"l":"C","t":"La détection d''une pseudarthrose","c":false},{"l":"D","t":"La présence rassurante d''un liseré hypodense autour du matériel d''ostéosynthèse","c":false},{"l":"E","t":"Seul le cliché de face doit être réalisé pour des raisons de radioprotection","c":false}]'::jsonb, NULL, '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2645, 15, 'Traumatologie', 'Traumatismes du poignet : fracture du poignet ; fracture des os du carpe', 'Mademoiselle E., 36 ans, consulte aux urgences pour douleurs et déformation du poignet gauche suite à une chute sur son lieu de travail. Elle aurait trébuché car « ses nouveaux escarpins sont bien trop hauts ». Cette secrétaire sans enfants n''a pas d''antécédent particulier. Vous réalisez les radios suivantes : 0'')', false, true, 'La patiente vous questionne à propos de la consolidation de l''os. Quelles sont les propositions vraies ?', '[{"l":"A","t":"Elle aurait été plus longue avec des broches","c":false},{"l":"B","t":"Une mise en compression importante du foyer de fracture peut augmenter le risque de pseudartrose par ischémie osseuse","c":false},{"l":"C","t":"L''évacuation de l''hématome péri-fracturaire facilite la consolidation","c":false},{"l":"D","t":"Les délais de consolidation normaux sont globalement plus longs aux extrémités","c":true},{"l":"E","t":"On peut parler de pseudarhtrose aseptique du poignet en cas de non-consolidation après 3 mois","c":true}]'::jsonb, NULL, '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2646, 15, 'Traumatologie', 'Traumatismes du poignet : fracture du poignet ; fracture des os du carpe', 'Mademoiselle E., 36 ans, consulte aux urgences pour douleurs et déformation du poignet gauche suite à une chute sur son lieu de travail. Elle aurait trébuché car « ses nouveaux escarpins sont bien trop hauts ». Cette secrétaire sans enfants n''a pas d''antécédent particulier. Vous réalisez les radios suivantes : 0'')', false, true, 'Madame E. souhaite déclarer sa fracture en tant qu''accident de travail. Quels sont les principes de la déclaration ?', '[{"l":"A","t":"Le médecin doit informer l''employeur dans les 24 h","c":false},{"l":"B","t":"L''employeur doit déclarer l''accident à la CPAM dans les 48 heures suivant la prise de connaissance de l''accident","c":true},{"l":"C","t":"Prise en charge à 1OO % des frais médicaux","c":true},{"l":"D","t":"Indemnités journalières après un délai de carence de 3jours","c":false},{"l":"E","t":"Tiers payant concernant les soins en rapport avec l''accident de travail o-r","c":true}]'::jsonb, NULL, '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2647, 35, 'Rhumatologie', 'Syndrome du canal carpien', 'Mademoiselle E., 36 ans, consulte aux urgences pour douleurs et déformation du poignet gauche suite à une chute sur son lieu de travail. Elle aurait trébuché car « ses nouveaux escarpins sont bien trop hauts ». Cette secrétaire sans enfants n''a pas d''antécédent particulier. Vous réalisez les radios suivantes : 0'')', false, true, 'Les suites opératoires de la patiente ont été simples. La rééducation s''est bien passée. Mme E. revient vous voir pour des sensations d''engourdissement de la main gauche, surtout la nuit. Ce type de douleur n''existait pas avant l''opération. Vous évoquez un syndrome du canal carpien, quels éléments cliniques sont en faveur ?', '[{"l":"A","t":"Paresthésies au test du Phalen","c":true},{"l":"B","t":"Paresthésies de topographie C5-C6-C7","c":false},{"l":"C","t":"Une amyotrophie hypothénarienne","c":false},{"l":"D","t":"Un déficit à l''opposition du pouce","c":true},{"l":"E","t":"Des paresthésies de trajet tronculaire","c":true}]'::jsonb, NULL, '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2648, 35, 'Rhumatologie', 'Syndrome du canal carpien', 'Mademoiselle E., 36 ans, consulte aux urgences pour douleurs et déformation du poignet gauche suite à une chute sur son lieu de travail. Elle aurait trébuché car « ses nouveaux escarpins sont bien trop hauts ». Cette secrétaire sans enfants n''a pas d''antécédent particulier. Vous réalisez les radios suivantes : 0'')', false, true, 'Quels éléments vous auraient orienté vers un syndrome du défilé cervico-thoraco-brachial ?', '[{"l":"A","t":"Un antécédent de thrombose veineuse du membre supérieur","c":true},{"l":"B","t":"Une manœuvre du « chandelier » positive","c":true},{"l":"C","t":"Des paresthésies de topographie plexique","c":true},{"l":"D","t":"Des paresthésies de topographie C8-T1","c":true},{"l":"E","t":"Une abolition du pouls radial, bras en l''air","c":true}]'::jsonb, NULL, '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2649, 35, 'Rhumatologie', 'Syndrome du canal carpien', 'Mademoiselle E., 36 ans, consulte aux urgences pour douleurs et déformation du poignet gauche suite à une chute sur son lieu de travail. Elle aurait trébuché car « ses nouveaux escarpins sont bien trop hauts ». Cette secrétaire sans enfants n''a pas d''antécédent particulier. Vous réalisez les radios suivantes : 0'')', false, true, 'OO Le tableau clinique est finalement celui d''un syndrome du canal carpien post-traumatique sans déficit moteur. Quels examens complémentaires vous semblent indispensables?', '[{"l":"A","t":"Électro-neuro-myogramme du membre supérieur","c":false},{"l":"B","t":"IRM du poignet","c":false},{"l":"C","t":"TDM du poignet","c":false},{"l":"D","t":"Échographie du poignet","c":false},{"l":"E","t":"Aucun","c":true}]'::jsonb, 'Conseil du spécialiste : En cas de canal carpien traumatique, une exploration peut être nécessaire par écho ou scanner pour voir les rapports anatomiques du nerf.', '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2650, 35, 'Rhumatologie', 'Syndrome du canal carpien', 'Mademoiselle E., 36 ans, consulte aux urgences pour douleurs et déformation du poignet gauche suite à une chute sur son lieu de travail. Elle aurait trébuché car « ses nouveaux escarpins sont bien trop hauts ». Cette secrétaire sans enfants n''a pas d''antécédent particulier. Vous réalisez les radios suivantes : 0'')', false, true, 'Vous faites finalement réaliser un EMG. Qu''en attendez-vous si le diagnostic se confirme ?', '[{"l":"A","t":"Absence d''anomalie en détection","c":true},{"l":"B","t":"Ralentissement des vitesses de conduction sensitives","c":true},{"l":"C","t":"Ralentissement des vitesses de conduction motrices","c":true},{"l":"D","t":"Ralentissement des vitesses dans le bras et l''avantbras","c":false},{"l":"E","t":"C''est l''EMG qui donnera l''indication de chirurgie","c":false}]'::jsonb, NULL, '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2651, 35, 'Rhumatologie', 'Syndrome du canal carpien', 'Mademoiselle E., 36 ans, consulte aux urgences pour douleurs et déformation du poignet gauche suite à une chute sur son lieu de travail. Elle aurait trébuché car « ses nouveaux escarpins sont bien trop hauts ». Cette secrétaire sans enfants n''a pas d''antécédent particulier. Vous réalisez les radios suivantes : 0'')', false, true, 'on Quel traitement médical proposez-vous ?', '[{"l":"A","t":"Arrêt de travail court","c":true},{"l":"B","t":"Attelle de fonction","c":true},{"l":"C","t":"Infiltrations de corticoïdes mensuelles","c":false},{"l":"D","t":"Infiltration de corticoïde au niveau du pli de poignet","c":true},{"l":"E","t":"Antiépileptiques si nécessaire","c":true}]'::jsonb, NULL, '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2652, 35, 'Rhumatologie', 'Syndrome du canal carpien', 'Mademoiselle E., 36 ans, consulte aux urgences pour douleurs et déformation du poignet gauche suite à une chute sur son lieu de travail. Elle aurait trébuché car « ses nouveaux escarpins sont bien trop hauts ». Cette secrétaire sans enfants n''a pas d''antécédent particulier. Vous réalisez les radios suivantes : 0'')', false, true, 'Quels sont les principes du traitement chirurgical ?', '[{"l":"A","t":"D''emblée en cas de déficit moteur","c":true},{"l":"B","t":"Section du ligament annulaire du carpe","c":true},{"l":"C","t":"Par méthode endoscopique","c":true},{"l":"D","t":"Par méthode « à ciel ouvert »","c":true},{"l":"E","t":"Neurolyse systématique","c":false}]'::jsonb, NULL, '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2653, 35, 'Rhumatologie', 'Syndrome du canal carpien', 'Mademoiselle E., 36 ans, consulte aux urgences pour douleurs et déformation du poignet gauche suite à une chute sur son lieu de travail. Elle aurait trébuché car « ses nouveaux escarpins sont bien trop hauts ». Cette secrétaire sans enfants n''a pas d''antécédent particulier. Vous réalisez les radios suivantes : 0'')', false, true, 'De quelles complications devez-vous informer la patiente ?', '[{"l":"A","t":"Perturbations neurologiques pouvant perdurer 6 mois","c":true},{"l":"B","t":"Une absence possible de récupération","c":true},{"l":"C","t":"Des lésions nerveuses ulnaires","c":true},{"l":"D","t":"Des lésions artérielles radiales","c":true},{"l":"E","t":"Des lésions tendineuses des extenseurs","c":false}]'::jsonb, NULL, '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2654, 34, 'Rhumatologie', 'Lombalgies et lombosciatalgies', 'Monsieur P, déménageur breton de 56 ans, se présente à votre consultation d''orthopédie pour des douleurs lombaires, il souhaite absolument se faire opérer. Ses douleurs évoluent depuis plusieurs années et ont entraîné de nombreux arrêts de travail. Les radiographies que le patient vous donne, prescrites par son médecin traitant, montrent une lombodiscarthrose modérée.', false, true, 'Les radiographies sont-elles indiquées chez ce patient ?', '[{"l":"A","t":"Oui si les douleurs ont duré plus de 7 jours consécutifs","c":false},{"l":"B","t":"Oui en cas de notion de traumatisme","c":true},{"l":"C","t":"Oui en cas de fièvre","c":true},{"l":"D","t":"Oui car le patient à plus de 50 ans","c":false},{"l":"E","t":"Oui en cas de syndrome de la queue-de-cheval","c":true}]'::jsonb, 'Conseil du spécialiste : Tout ce qui évoque une lombalgie symptomatique doit motiver la réalisation d''un bilan paraclinique. Idem si les douleurs durent depuis plus de 7 semaines.', '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2655, 34, 'Rhumatologie', 'Lombalgies et lombosciatalgies', 'Monsieur P, déménageur breton de 56 ans, se présente à votre consultation d''orthopédie pour des douleurs lombaires, il souhaite absolument se faire opérer. Ses douleurs évoluent depuis plusieurs années et ont entraîné de nombreux arrêts de travail. Les radiographies que le patient vous donne, prescrites par son médecin traitant, montrent une lombodiscarthrose modérée.', false, true, 'À l''examen clinique, vous retrouvez un syndrome rachidien sans signe de conflit disco-radiculaire. L''examen clinique est normal par ailleurs. Quels éléments avez-vous trouvés au cours de votre examen clinique ?', '[{"l":"A","t":"Un signe de Lasègue positif","c":false},{"l":"B","t":"Un signe de Léri positif","c":false},{"l":"C","t":"Un indice de Shober augmenté","c":false},{"l":"D","t":"Une contracture para-vertébrale","c":true},{"l":"E","t":"Un signe de la sonnette","c":false}]'::jsonb, NULL, '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2656, 24, 'Rhumatologie', 'Traumatismes vertébraux-médullaires', 'Monsieur P, déménageur breton de 56 ans, se présente à votre consultation d''orthopédie pour des douleurs lombaires, il souhaite absolument se faire opérer. Ses douleurs évoluent depuis plusieurs années et ont entraîné de nombreux arrêts de travail. Les radiographies que le patient vous donne, prescrites par son médecin traitant, montrent une lombodiscarthrose modérée.', false, true, 'Que dites-vous au patient concernant le recours à la chirurgie dans son cas ?', '[{"l":"A","t":"Une cure de hernie aurait peu d''effet sur les douleurs lombaires","c":true},{"l":"B","t":"Une nucléotomie laser est recommandée","c":false},{"l":"C","t":"Une laminectomie est recommandée","c":false},{"l":"D","t":"Une douleur persistante plusieurs mois sous traitement médicamenteux est une indication au traitement chirurgical","c":false},{"l":"E","t":"Elle ne peut être réalisée que par un neurochirurgien","c":false}]'::jsonb, 'Conseil du spécialiste : Attention la chirurgie n''est rentable qu''en cas de conflit radiculaire, elle n''a pas d''effet sur les douleurs lombaires isolées.', '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2657, 34, 'Rhumatologie', 'Lombalgies et lombosciatalgies', 'Monsieur P, déménageur breton de 56 ans, se présente à votre consultation d''orthopédie pour des douleurs lombaires, il souhaite absolument se faire opérer. Ses douleurs évoluent depuis plusieurs années et ont entraîné de nombreux arrêts de travail. Les radiographies que le patient vous donne, prescrites par son médecin traitant, montrent une lombodiscarthrose modérée.', false, true, 'nA Finalement, le patient repart très déçu que vous n''ayez pas une solution miracle à lui proposer. li revient vous voir 1 an plus tard car ses douleurs sont devenues insupportables. Elles le réveillent la nuit et monsieur P. se sent très fatigué. Cette situation a fini par l''inquiéter, il a d''ailleurs perdu 5 kilos. Les douleurs intéressent l''ensemble du rachis. Vous diagnostiquez une sciatique droite sans signe de gravité. Quels éléments sémiologiques retrouvez-vous du côté droit en faveur de votre diagnostic ?', '[{"l":"A","t":"Déficit à la marche sur les talons < 3/5","c":false},{"l":"B","t":"Un signe de Babinski","c":false},{"l":"C","t":"Un signe de Lasègue","c":true},{"l":"D","t":"Un signe de Léri","c":false},{"l":"E","t":"Une douleur majorée à la toux","c":true}]'::jsonb, NULL, '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2658, 30, 'Orthopédie', 'Tumeurs osseuses (bénignes et malignes)', 'Monsieur P, déménageur breton de 56 ans, se présente à votre consultation d''orthopédie pour des douleurs lombaires, il souhaite absolument se faire opérer. Ses douleurs évoluent depuis plusieurs années et ont entraîné de nombreux arrêts de travail. Les radiographies que le patient vous donne, prescrites par son médecin traitant, montrent une lombodiscarthrose modérée.', false, true, 'Quel bilan paraclinique prescrivez-vous ?', '[{"l":"A","t":"Scanner du rachis cervico-dorso-lombaire","c":true},{"l":"B","t":"IRM cérébrale et médullaire","c":false},{"l":"C","t":"Sacco-radiculographie","c":false},{"l":"D","t":"EMG des membres inférieurs","c":false},{"l":"E","t":"Aucun examen complémentaire en première intention chez ce patient ne","c":false}]'::jsonb, NULL, '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2659, 10, 'Orthopédie', 'Ostéopathies reminéralisantes (ostéoporose, ostéomalacie)', 'Monsieur P, déménageur breton de 56 ans, se présente à votre consultation d''orthopédie pour des douleurs lombaires, il souhaite absolument se faire opérer. Ses douleurs évoluent depuis plusieurs années et ont entraîné de nombreux arrêts de travail. Les radiographies que le patient vous donne, prescrites par son médecin traitant, montrent une lombodiscarthrose modérée.', false, true, 'Parmi ces propositions, lesquelles vous semblent compatibles avec un aspect de vertèbre hyperdense ?', '[{"l":"A","t":"Métastase de carcinome prostatique","c":true},{"l":"B","t":"Maladie de Paget","c":true},{"l":"C","t":"Lymphome primitif","c":true},{"l":"D","t":"Métastase de cancer du sein","c":true},{"l":"E","t":"Myélome multiple","c":true}]'::jsonb, NULL, '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2660, 10, 'Orthopédie', 'Ostéopathies reminéralisantes (ostéoporose, ostéomalacie)', 'Monsieur P, déménageur breton de 56 ans, se présente à votre consultation d''orthopédie pour des douleurs lombaires, il souhaite absolument se faire opérer. Ses douleurs évoluent depuis plusieurs années et ont entraîné de nombreux arrêts de travail. Les radiographies que le patient vous donne, prescrites par son médecin traitant, montrent une lombodiscarthrose modérée.', false, true, 'Quelle est ici votre hypothèse diagnostique principale chez ce patient ?', '[{"l":"A","t":"Discarthrose sévère","c":false},{"l":"B","t":"Adénocarcinome prostatique métastatique","c":true},{"l":"C","t":"Maladie de Paget","c":false},{"l":"D","t":"Lymphome osseux","c":false},{"l":"E","t":"SAPHO","c":false}]'::jsonb, NULL, '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2661, 30, 'Orthopédie', 'Tumeurs osseuses (bénignes et malignes)', 'Monsieur P, déménageur breton de 56 ans, se présente à votre consultation d''orthopédie pour des douleurs lombaires, il souhaite absolument se faire opérer. Ses douleurs évoluent depuis plusieurs années et ont entraîné de nombreux arrêts de travail. Les radiographies que le patient vous donne, prescrites par son médecin traitant, montrent une lombodiscarthrose modérée.', false, true, 'Vous réalisez un toucher rectal qui retrouve une grosse prostate pierreuse et un blindage pelvien. Vous faites doser les PSA totaux qui sont à 100 ng/ml. Quel bilan paraclinique prévoyez-vous alors ?', '[{"l":"A","t":"Dosage du rapport PSA libre sur PSA totaux","c":false},{"l":"B","t":"Biopsies prostatiques par voie transrectale","c":true},{"l":"C","t":"IRM prostatique","c":true},{"l":"D","t":"ECBU","c":true},{"l":"E","t":"Scintigraphie osseuse","c":true}]'::jsonb, NULL, '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2662, 30, 'Orthopédie', 'Tumeurs osseuses (bénignes et malignes)', 'Monsieur P, déménageur breton de 56 ans, se présente à votre consultation d''orthopédie pour des douleurs lombaires, il souhaite absolument se faire opérer. Ses douleurs évoluent depuis plusieurs années et ont entraîné de nombreux arrêts de travail. Les radiographies que le patient vous donne, prescrites par son médecin traitant, montrent une lombodiscarthrose modérée.', false, true, 'Le patient est hospitalisé pour faire le bilan nécessaire, son état général s''est dégradé rapidement, il vomit et décrit des douleurs abdominales diffuses ainsi que des palpitations. Vous retrouvez un syndrome polyuro-polydipsique, un pli cutané persistant, une tachycardie et une tension à 95/70. Quelle est votre hypothèse diagnostique principale ?', '[{"l":"A","t":"Métastase cérébrale","c":false},{"l":"B","t":"Compression médullaire thoracique","c":false},{"l":"C","t":"Rétention aiguë d''urine","c":false},{"l":"D","t":"Hypercalcémie maligne","c":true},{"l":"E","t":"Diabète décompensé","c":false}]'::jsonb, NULL, '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2663, 30, 'Orthopédie', 'Tumeurs osseuses (bénignes et malignes)', 'Monsieur P, déménageur breton de 56 ans, se présente à votre consultation d''orthopédie pour des douleurs lombaires, il souhaite absolument se faire opérer. Ses douleurs évoluent depuis plusieurs années et ont entraîné de nombreux arrêts de travail. Les radiographies que le patient vous donne, prescrites par son médecin traitant, montrent une lombodiscarthrose modérée.', false, true, 'no Quelle est votre prise en charge si votre diagnostic se confirme?', '[{"l":"A","t":"Transfert en unité de soins intensifs","c":true},{"l":"B","t":"Diurèse forcée par un diurétique de l''anse sans attendre","c":false},{"l":"C","t":"Corticoïdes IV","c":true},{"l":"D","t":"Épuration extra-rénale d''emblée","c":false},{"l":"E","t":"Hydratation massive IV par du NaCI 0,9 %","c":true}]'::jsonb, 'Conseil du spécialiste : Attention, dans l''hypercalcémie ne jamais parler de diurèse forcée sans parler d''hyperhydratation avant.', '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2664, 30, 'Orthopédie', 'Tumeurs osseuses (bénignes et malignes)', 'Monsieur P, déménageur breton de 56 ans, se présente à votre consultation d''orthopédie pour des douleurs lombaires, il souhaite absolument se faire opérer. Ses douleurs évoluent depuis plusieurs années et ont entraîné de nombreux arrêts de travail. Les radiographies que le patient vous donne, prescrites par son médecin traitant, montrent une lombodiscarthrose modérée.', false, true, 'Quel traitement spécifique sur le plan carcinologique est adapté sachant que le bilan d''extension retrouve un score de Gleason à 10, des adénopathies pelviennes et que les lésions rachidiennes sont bien des localisations secondaires ?', '[{"l":"A","t":"Traitement palliatif","c":true},{"l":"B","t":"Prostatectomie totale","c":false},{"l":"C","t":"Lymphadénectomie ilio-obturatrice","c":false},{"l":"D","t":"Hormonothérapie par anti-androgènes et antagonistes de la LHRH","c":false},{"l":"E","t":"Pulpectomie bilatérale","c":true}]'::jsonb, NULL, '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2665, 30, 'Orthopédie', 'Tumeurs osseuses (bénignes et malignes)', 'Monsieur P, déménageur breton de 56 ans, se présente à votre consultation d''orthopédie pour des douleurs lombaires, il souhaite absolument se faire opérer. Ses douleurs évoluent depuis plusieurs années et ont entraîné de nombreux arrêts de travail. Les radiographies que le patient vous donne, prescrites par son médecin traitant, montrent une lombodiscarthrose modérée.', false, true, 'nn Quelle est votre prise en charge des douleurs rachidiennes?', '[{"l":"A","t":"Radiothérapie","c":true},{"l":"B","t":"Hormonothérapie","c":true},{"l":"C","t":"Biphosphonates","c":true},{"l":"D","t":"Chirurgie décompressive","c":true},{"l":"E","t":"Anticonvulsivants","c":true}]'::jsonb, NULL, '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2666, 30, 'Orthopédie', 'Tumeurs osseuses (bénignes et malignes)', 'Monsieur P, déménageur breton de 56 ans, se présente à votre consultation d''orthopédie pour des douleurs lombaires, il souhaite absolument se faire opérer. Ses douleurs évoluent depuis plusieurs années et ont entraîné de nombreux arrêts de travail. Les radiographies que le patient vous donne, prescrites par son médecin traitant, montrent une lombodiscarthrose modérée.', false, true, 'Vous optez en accord avec le patient pour un blocage androgénique complet par hormonothérapie. Rapidement après introduction du traitement, les douleurs osseuses de Monsieur P. s''aggravent. Quelles propositions sont vraies ?', '[{"l":"A","t":"Il s''agit d''une flambée androgénique","c":true},{"l":"B","t":"Il s''agit d''un signe de résistance au traitement hormonal","c":false},{"l":"C","t":"Ces douleurs peuvent être prévenues par l''introduction de LH RH, 15 jours avant les anti-androgènes","c":false},{"l":"D","t":"Ces douleurs peuvent être prévenues par une chimiothérapie non ciblée concomitante","c":false},{"l":"E","t":"Il faut arrêter immédiatement l''hormonothérapie","c":false}]'::jsonb, 'Conseil du spécialiste : Pour éviter la flambée androgénique, il faut prescrire une bithérapie par analogue de la LHRH et anti-androgène pendant le premier mois.', '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2667, 10, 'Orthopédie', 'Tumeurs osseuses (bénignes et malignes)', 'Monsieur P, déménageur breton de 56 ans, se présente à votre consultation d''orthopédie pour des douleurs lombaires, il souhaite absolument se faire opérer. Ses douleurs évoluent depuis plusieurs années et ont entraîné de nombreux arrêts de travail. Les radiographies que le patient vous donne, prescrites par son médecin traitant, montrent une lombodiscarthrose modérée.', false, true, 'Le cancer de Monsieur P. a bien répondu à la bi-horrnonothérapie pendant 2 ans. li s''est récemment fracturé les deux poignets suite à une chute de sa hauteur. Son taux de PSA est à 0, 1 ng/ml. Quelle explication est la plus probable ?', '[{"l":"A","t":"Métastases osseuses du squelette périphérique","c":false},{"l":"B","t":"Ostéoporose secondaire","c":true},{"l":"C","t":"Ostéomalacie","c":false},{"l":"D","t":"Dénutrition","c":false},{"l":"E","t":"Hypogonadisme","c":true}]'::jsonb, NULL, '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2668, 19, 'Traumatologie', 'Traumatismes de l’épaule : luxation de l’épaule ; disjonction acromio-claviculaire', 'Vous recevez Monsieur A., 20 ans et apparemment en état d''ébriété, pour douleurs de l''épaule droite après avoir chuté dans le petit bassin d''une piscine vide. Le patient dit avoir chuté sur la paume de la main droite. Sa douleur est évaluée à 7011 OO selon l''EVA.', false, true, 'Quelle déformation attendez-vous en cas de luxation gléna-humérale antéro-interne sans lésion associée ?', '[{"l":"A","t":"Attitude vicieuse en adduction","c":false},{"l":"B","t":"Attitude vicieuse en rotation externe","c":true},{"l":"C","t":"Comblement du sillon delta-pectoral","c":true},{"l":"D","t":"Vacuité glénoïdienne à la palpation","c":true},{"l":"E","t":"Signe de Berger","c":true}]'::jsonb, NULL, '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2669, 19, 'Traumatologie', 'Traumatismes de l’épaule : luxation de l’épaule ; disjonction acromio-claviculaire', 'Vous recevez Monsieur A., 20 ans et apparemment en état d''ébriété, pour douleurs de l''épaule droite après avoir chuté dans le petit bassin d''une piscine vide. Le patient dit avoir chuté sur la paume de la main droite. Sa douleur est évaluée à 7011 OO selon l''EVA.', false, true, 'Quelles complications recherchez-vous cliniquement ?', '[{"l":"A","t":"Une lésion du nerf axillaire par un testing sensitif du moignon de l''épaule","c":true},{"l":"B","t":"Une lésion du nerf accessoire par un testing de la contraction isométrique du deltoïde","c":true},{"l":"C","t":"Une lésion du tendon supra-épineux par la manœuvre de Jobe","c":false},{"l":"D","t":"Une lésion du tendon bicipital par la manœuvre de Patte","c":false},{"l":"E","t":"La recherche des complications doit être faite avant ou après réduction","c":false}]'::jsonb, NULL, '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2670, 19, 'Traumatologie', 'Traumatismes de l’épaule : luxation de l’épaule ; disjonction acromio-claviculaire', 'Vous recevez Monsieur A., 20 ans et apparemment en état d''ébriété, pour douleurs de l''épaule droite après avoir chuté dans le petit bassin d''une piscine vide. Le patient dit avoir chuté sur la paume de la main droite. Sa douleur est évaluée à 7011 OO selon l''EVA.', false, true, 'Quel est votre traitement ?', '[{"l":"A","t":"Morphine par voie sous-cutanée","c":true},{"l":"B","t":"Réduction au bloc opératoire sous anesthésie générale","c":false},{"l":"C","t":"Réduction sous MEOPA aux urgences","c":true},{"l":"D","t":"Traitement par ostéosynthèse","c":false},{"l":"E","t":"Benzodiazépine IV en cas de contracture importante du deltoïde","c":false}]'::jsonb, NULL, '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2671, 19, 'Traumatologie', 'Traumatismes de l’épaule : luxation de l’épaule ; disjonction acromio-claviculaire', 'Vous recevez Monsieur A., 20 ans et apparemment en état d''ébriété, pour douleurs de l''épaule droite après avoir chuté dans le petit bassin d''une piscine vide. Le patient dit avoir chuté sur la paume de la main droite. Sa douleur est évaluée à 7011 OO selon l''EVA.', false, true, 'Quelle est la conduite à tenir ensuite ?', '[{"l":"A","t":"Immobilisation 3 jours par bandage coude au corps","c":false},{"l":"B","t":"Immobilisation plusieurs semaines par Dujarier ou Mayo Clinic.","c":true},{"l":"C","t":"Radiographie de contrôle après réduction le jour même","c":true},{"l":"D","t":"Radiographie de contrôle à J7","c":false},{"l":"E","t":"La kinésithérapie ne débutera qu''à l''ablation de l''immobilisation","c":false}]'::jsonb, NULL, '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2672, 39, 'Traumatologie', 'Fracture du cou-de-pied : fracture malléolaire, fracture du pilon tibial', 'Vous recevez Monsieur A., 20 ans et apparemment en état d''ébriété, pour douleurs de l''épaule droite après avoir chuté dans le petit bassin d''une piscine vide. Le patient dit avoir chuté sur la paume de la main droite. Sa douleur est évaluée à 7011 OO selon l''EVA.', false, true, 'Quelques mois plus tard, Monsieur A. est de retour aux urgences pour douleurs de la cheville droite suite à un faux pas au cours d''une soirée bien arrosée. Le patient est Glasgow 14, il présente un nystagmus et un syndrome cérébelleux, des vomissements et une hétéroagressivité certaine. Son taux d''alcoolémie est de 3 g/I. Quelle est votre conduite à tenir concernant l''ivresse pathologique du patient ?', '[{"l":"A","t":"Transfert en réanimation","c":false},{"l":"B","t":"Hydratation per os","c":false},{"l":"C","t":"Hydratation IV par du NaCI 0,9 %","c":true},{"l":"D","t":"Benzodiazépine IV","c":false},{"l":"E","t":"Glycémie capillaire","c":true}]'::jsonb, NULL, '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2673, 39, 'Traumatologie', 'Fracture du cou-de-pied : fracture malléolaire, fracture du pilon tibial', 'Vous recevez Monsieur A., 20 ans et apparemment en état d''ébriété, pour douleurs de l''épaule droite après avoir chuté dans le petit bassin d''une piscine vide. Le patient dit avoir chuté sur la paume de la main droite. Sa douleur est évaluée à 7011 OO selon l''EVA.', false, true, 'Quelques dizaines de minute plus tard, l''état du patient s''est amélioré et celui-ci devient examinable. Il décrit un mouvement d''inversion forcée de sa cheville droite. Quels sont les mouvements qui caractérisent l''inversion du pied ?', '[{"l":"A","t":"Flexion dorsale","c":false},{"l":"B","t":"Supination","c":true},{"l":"C","t":"Adduction","c":true},{"l":"D","t":"Rotation externe","c":false},{"l":"E","t":"Position en varus équin","c":true}]'::jsonb, NULL, '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2674, 39, 'Traumatologie', 'Fracture du cou-de-pied : fracture malléolaire, fracture du pilon tibial', 'Vous recevez Monsieur A., 20 ans et apparemment en état d''ébriété, pour douleurs de l''épaule droite après avoir chuté dans le petit bassin d''une piscine vide. Le patient dit avoir chuté sur la paume de la main droite. Sa douleur est évaluée à 7011 OO selon l''EVA.', false, true, 'Quels sont les signes d''entorse grave que vous recherchez?', '[{"l":"A","t":"Hématome malléolaire externe en œuf de pigeon","c":true},{"l":"B","t":"Impotence fonctionnelle totale différée","c":false},{"l":"C","t":"Douleur très importante","c":false},{"l":"D","t":"Craquement audible au moment du trauma","c":true},{"l":"E","t":"Bâillement tibio-astragalien spontané","c":true}]'::jsonb, NULL, '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2675, 39, 'Traumatologie', 'Fracture du cou-de-pied : fracture malléolaire, fracture du pilon tibial', 'Vous recevez Monsieur A., 20 ans et apparemment en état d''ébriété, pour douleurs de l''épaule droite après avoir chuté dans le petit bassin d''une piscine vide. Le patient dit avoir chuté sur la paume de la main droite. Sa douleur est évaluée à 7011 OO selon l''EVA.', false, true, 'À propos des radiographies de la cheville en cas d''entorse:', '[{"l":"A","t":"Elles sont indiquées ici devant l''âge du patient","c":false},{"l":"B","t":"Elles sont indiquées en cas de douleur déclenchée à la palpation du dos du pied","c":true},{"l":"C","t":"Elles sont indiquées si le patient ne peut pas se mettre en appui sur la cheville","c":true},{"l":"D","t":"Elles sont indiquées en cas de douleur déclenchée à la palpation de la base du 5 ème métacarpien","c":false},{"l":"E","t":"Les radiographies dynamiques doivent être faites dès que possible en cas d''entorse grave","c":false}]'::jsonb, NULL, '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2676, 39, 'Traumatologie', 'Fracture du cou-de-pied : fracture malléolaire, fracture du pilon tibial', 'Vous recevez Monsieur A., 20 ans et apparemment en état d''ébriété, pour douleurs de l''épaule droite après avoir chuté dans le petit bassin d''une piscine vide. Le patient dit avoir chuté sur la paume de la main droite. Sa douleur est évaluée à 7011 OO selon l''EVA.', false, true, 'Finalement vous ne faites pas de radiographie. L''entorse ne présente pas de signe de gravité clinique. Les douleurs sont bien calmées par le paracétamol. Quelles sont vos prescriptions aux urgences ?', '[{"l":"A","t":"Décharge du membre inférieur droit","c":true},{"l":"B","t":"Cryothérapie","c":true},{"l":"C","t":"Immobilisation par botte plâtrée bivalvée","c":false},{"l":"D","t":"Anticoagulation préventive","c":false},{"l":"E","t":"Orthèse semi-rigide","c":true}]'::jsonb, NULL, '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2677, 39, 'Traumatologie', 'Fracture du cou-de-pied : fracture malléolaire, fracture du pilon tibial', 'Vous recevez Monsieur A., 20 ans et apparemment en état d''ébriété, pour douleurs de l''épaule droite après avoir chuté dans le petit bassin d''une piscine vide. Le patient dit avoir chuté sur la paume de la main droite. Sa douleur est évaluée à 7011 OO selon l''EVA.', false, true, 'Quelle est la conduite à tenir à moyen terme ?', '[{"l":"A","t":"Consultation à J7 obligatoire","c":true},{"l":"B","t":"Maintien de l''immobilisation pour 3 semaines avec appui même en absence de douleur","c":false},{"l":"C","t":"Reprise de l''appui avec la sédation de la douleur","c":true},{"l":"D","t":"Reprise des activités sportives avec la sédation de la douleur","c":false},{"l":"E","t":"La consultation à distance est le seul moyen d''évaluer la gravité réelle de l''entorse","c":true}]'::jsonb, NULL, '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2678, 39, 'Traumatologie', 'Fracture du cou-de-pied : fracture malléolaire, fracture du pilon tibial', 'Vous recevez Monsieur A., 20 ans et apparemment en état d''ébriété, pour douleurs de l''épaule droite après avoir chuté dans le petit bassin d''une piscine vide. Le patient dit avoir chuté sur la paume de la main droite. Sa douleur est évaluée à 7011 OO selon l''EVA.', false, true, 'Vous réalisez un court arrêt de travail, quelles en sont les modalités ?', '[{"l":"A","t":"Le patient doit envoyer son avis d''arrêt de travail sous 48 h","c":true},{"l":"B","t":"Le patient devra envoyer les volets 1 et 2 au service médical de sa caisse d''Assurance Maladie et le volet 3 à son employeur","c":true},{"l":"C","t":"L''indemnité journalière que recevra le patient est égale à 50 % de son salaire journalier de base.","c":true},{"l":"D","t":"Il n''y a pas de délai de carence","c":false},{"l":"E","t":"Les frais médicaux en rapport sont pris en charge à 1OO %","c":false}]'::jsonb, NULL, '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2679, 29, 'Traumatologie', 'Algoneurodystrophie', 'Vous recevez Monsieur A., 20 ans et apparemment en état d''ébriété, pour douleurs de l''épaule droite après avoir chuté dans le petit bassin d''une piscine vide. Le patient dit avoir chuté sur la paume de la main droite. Sa douleur est évaluée à 7011 OO selon l''EVA.', false, true, 'Quelles complications sont possibles à distance ?', '[{"l":"A","t":"Raideur","c":true},{"l":"B","t":"Algodystrophie","c":true},{"l":"C","t":"Récidive","c":true},{"l":"D","t":"Arthrose tibio-talienne","c":true},{"l":"E","t":"Ostéonécrose aseptique talienne","c":false}]'::jsonb, NULL, '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2680, 19, 'Traumatologie', 'Traumatismes de l’épaule : luxation de l’épaule ; disjonction acromio-claviculaire', 'Vous recevez Monsieur A., 20 ans et apparemment en état d''ébriété, pour douleurs de l''épaule droite après avoir chuté dans le petit bassin d''une piscine vide. Le patient dit avoir chuté sur la paume de la main droite. Sa douleur est évaluée à 7011 OO selon l''EVA.', false, true, 'Monsieur P. décrit des ressauts douloureux au niveau de l''épaule droite presque à chaque fois qu''il lance quelque chose ou qu''il attrape un objet derrière lui avec son bras droit. Quelles sont les propositions vraies ?', '[{"l":"A","t":"Vous évoquez une instabilité postérieure","c":false},{"l":"B","t":"Le mouvement facilitant les subluxations est en abduction, rétropulsion, rotation externe","c":true},{"l":"C","t":"Cette complication peut être traitée chirurgicalement","c":true},{"l":"D","t":"Cette complication nécessite une acromioplastie","c":false},{"l":"E","t":"Le testing de l''épaule controlatérale doit être évité dans une logique d''épargne articulaire","c":false}]'::jsonb, NULL, '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2681, 8, 'Traumatologie', 'Généralités sur les fractures de l’adulte', 'Monsieur V, 37 ans, est amené par le SAMU pour trauma suite à une chute d''escalade. Il a dévalé 15 mètres de falaise avant que son baudrier ne le retienne et a fini sa chute en s''écrasant contre la paroi. Il était casqué au moment de l''examen et n''aurait pas perdu connaissance. Son état s''est rapidement aggravé dans l''ambulance. À l''arrivée aux urgences, le patient parle de manière inappropriée, ses yeux s''ouvrent quand vous lui parlez. Il repousse votre main avec son bras gauche quand vous lui pincez le bras droit. Le patient est pâle et marbré aux membres inférieurs. Sa tension artérielle est à 89176 mmHg et sa fréquence cardiaque est à 112 bpm, sa saturation est à 80 %. Il semble être douloureux à la palpation abdominale et au niveau des côtes. Sa cuisse droite et sa jambe gauche sont déformées. Le sondage ramène une hématurie.', false, true, 'Quel est le score de Glasgow de ce patient ?', '[{"l":"A","t":"8","c":false},{"l":"B","t":"9","c":false},{"l":"C","t":"10","c":false},{"l":"D","t":"11","c":true},{"l":"E","t":"12","c":false}]'::jsonb, 'Conseil du spécialiste : Y3V3M5.', '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2682, 8, 'Traumatologie', 'Généralités sur les fractures de l’adulte', 'Monsieur V, 37 ans, est amené par le SAMU pour trauma suite à une chute d''escalade. Il a dévalé 15 mètres de falaise avant que son baudrier ne le retienne et a fini sa chute en s''écrasant contre la paroi. Il était casqué au moment de l''examen et n''aurait pas perdu connaissance. Son état s''est rapidement aggravé dans l''ambulance. À l''arrivée aux urgences, le patient parle de manière inappropriée, ses yeux s''ouvrent quand vous lui parlez. Il repousse votre main avec son bras gauche quand vous lui pincez le bras droit. Le patient est pâle et marbré aux membres inférieurs. Sa tension artérielle est à 89176 mmHg et sa fréquence cardiaque est à 112 bpm, sa saturation est à 80 %. Il semble être douloureux à la palpation abdominale et au niveau des côtes. Sa cuisse droite et sa jambe gauche sont déformées. Le sondage ramène une hématurie.', false, true, 'Quelles sont les deux mesures à réaliser sans attendre ?', '[{"l":"A","t":"Glycémie capillaire","c":true},{"l":"B","t":"Hémoglobine capillaire","c":true},{"l":"C","t":"Tco2 capillaire","c":false},{"l":"D","t":"Bandelette urinaire","c":false},{"l":"E","t":"Température","c":false}]'::jsonb, 'Conseil du spécialiste : Hématurie = penser au traumatisme pelvien, au risque hémorragique I trouble de la conscience = glycémie.', '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2683, 8, 'Traumatologie', 'Généralités sur les fractures de l’adulte', 'Monsieur V, 37 ans, est amené par le SAMU pour trauma suite à une chute d''escalade. Il a dévalé 15 mètres de falaise avant que son baudrier ne le retienne et a fini sa chute en s''écrasant contre la paroi. Il était casqué au moment de l''examen et n''aurait pas perdu connaissance. Son état s''est rapidement aggravé dans l''ambulance. À l''arrivée aux urgences, le patient parle de manière inappropriée, ses yeux s''ouvrent quand vous lui parlez. Il repousse votre main avec son bras gauche quand vous lui pincez le bras droit. Le patient est pâle et marbré aux membres inférieurs. Sa tension artérielle est à 89176 mmHg et sa fréquence cardiaque est à 112 bpm, sa saturation est à 80 %. Il semble être douloureux à la palpation abdominale et au niveau des côtes. Sa cuisse droite et sa jambe gauche sont déformées. Le sondage ramène une hématurie.', false, true, 'Quel est votre bilan d''imagerie ?', '[{"l":"A","t":"Radiographie de thorax","c":true},{"l":"B","t":"Radiographie du bassin","c":true},{"l":"C","t":"Écho abdominale de type « fast écho »","c":true},{"l":"D","t":"Radiographie de la jambe droite","c":true},{"l":"E","t":"TOM corps entier","c":false}]'::jsonb, 'Conseil du spécialiste : Pas de bodyTDM en cas d''instabilité hémodynamique.', '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2684, 26, 'Traumatologie', 'Traumatisme du bassin : fracture, luxation traumatique de la hanche', 'Monsieur V, 37 ans, est amené par le SAMU pour trauma suite à une chute d''escalade. Il a dévalé 15 mètres de falaise avant que son baudrier ne le retienne et a fini sa chute en s''écrasant contre la paroi. Il était casqué au moment de l''examen et n''aurait pas perdu connaissance. Son état s''est rapidement aggravé dans l''ambulance. À l''arrivée aux urgences, le patient parle de manière inappropriée, ses yeux s''ouvrent quand vous lui parlez. Il repousse votre main avec son bras gauche quand vous lui pincez le bras droit. Le patient est pâle et marbré aux membres inférieurs. Sa tension artérielle est à 89176 mmHg et sa fréquence cardiaque est à 112 bpm, sa saturation est à 80 %. Il semble être douloureux à la palpation abdominale et au niveau des côtes. Sa cuisse droite et sa jambe gauche sont déformées. Le sondage ramène une hématurie.', false, true, 'Quelles propositions sont compatibles avec la dégradation hémodynamique du patient?', '[{"l":"A","t":"État de choc distributif","c":false},{"l":"B","t":"État de choc hémorragique","c":true},{"l":"C","t":"État de choc hypovolémique","c":true},{"l":"D","t":"Fracture d''un organe plein","c":true},{"l":"E","t":"Fracture du bassin","c":true}]'::jsonb, 'Conseil du spécialiste : Pression artérielle pincée donc pas d''état de choc distributif. Hypovolémique = hémorragique. Penser à la fracture de foie, de rate, à l''hématome rétro-péritonéal ou à l''hémopéritoine.', '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2685, 26, 'Traumatologie', 'Traumatisme du bassin : fracture, luxation traumatique de la hanche', 'Monsieur V, 37 ans, est amené par le SAMU pour trauma suite à une chute d''escalade. Il a dévalé 15 mètres de falaise avant que son baudrier ne le retienne et a fini sa chute en s''écrasant contre la paroi. Il était casqué au moment de l''examen et n''aurait pas perdu connaissance. Son état s''est rapidement aggravé dans l''ambulance. À l''arrivée aux urgences, le patient parle de manière inappropriée, ses yeux s''ouvrent quand vous lui parlez. Il repousse votre main avec son bras gauche quand vous lui pincez le bras droit. Le patient est pâle et marbré aux membres inférieurs. Sa tension artérielle est à 89176 mmHg et sa fréquence cardiaque est à 112 bpm, sa saturation est à 80 %. Il semble être douloureux à la palpation abdominale et au niveau des côtes. Sa cuisse droite et sa jambe gauche sont déformées. Le sondage ramène une hématurie.', false, true, 'Le bilan radiologique retrouve finalement une fracture non comminutive, non articulaire de la diaphyse fémoraie droite, une fracture du tibia gauche non comminutive non articulaire, une fracture du bassin complexe avec plaie vasculaire pelvienne et des fractures des 10 et 11e côtes droites sans complication. À propos des complications, quelles sont les propositions vraies?', '[{"l":"A","t":"Vous avez recherché une abolition du murmure vésiculaire à droite","c":true},{"l":"B","t":"Un hématome rétro-péritonéal est le plus souvent en rapport avec une rupture de rate","c":false},{"l":"C","t":"Les ouvertures cutanées sont rares dans les fractures diaphysaires fémorales","c":false},{"l":"D","t":"Les complications vasculo-nerveuses sont rares dans les fractures diaphysaires fémorales","c":true},{"l":"E","t":"Les lésions vasculaires sont rares dans les traumatismes du bassin","c":false}]'::jsonb, 'Conseil du spécialiste : Les fractures du bassin sont souvent hémorragiques (hématome rétropéritonéal). L''intérêt d''une radio de thorax dans les fractures de côte est de diagnostiquer un pneumothorax ou un hémothorax, la fracture de côte non compliquée ne change pas la prise en charge.', '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2686, 8, 'Traumatologie', 'Généralités sur les fractures de l’adulte', 'Monsieur V, 37 ans, est amené par le SAMU pour trauma suite à une chute d''escalade. Il a dévalé 15 mètres de falaise avant que son baudrier ne le retienne et a fini sa chute en s''écrasant contre la paroi. Il était casqué au moment de l''examen et n''aurait pas perdu connaissance. Son état s''est rapidement aggravé dans l''ambulance. À l''arrivée aux urgences, le patient parle de manière inappropriée, ses yeux s''ouvrent quand vous lui parlez. Il repousse votre main avec son bras gauche quand vous lui pincez le bras droit. Le patient est pâle et marbré aux membres inférieurs. Sa tension artérielle est à 89176 mmHg et sa fréquence cardiaque est à 112 bpm, sa saturation est à 80 %. Il semble être douloureux à la palpation abdominale et au niveau des côtes. Sa cuisse droite et sa jambe gauche sont déformées. Le sondage ramène une hématurie.', false, true, 'Vous souhaitez démarrer une transfusion de culots globulaires d''extrême urgence, quelles sont les propositions vraies ?', '[{"l":"A","t":"Il faut transfuser au patient un culot 0 RH 1 KEL -1","c":true},{"l":"B","t":"Il faut attendre le résultat du bilan pré-transfusionnel dans tous les cas","c":false},{"l":"C","t":"La possession d''une carte de don du sang sans doute sur l''identité du patient permet la transfusion de culots compatibles sans attendre le bilan transfusionnel.","c":true},{"l":"D","t":"Les culots transfusés seraient les mêmes si le patient était une femme du même âge.","c":false},{"l":"E","t":"Il est recommandé d''associer une transfusion de plasma et de plaquettes en cas de transfusion massive","c":true}]'::jsonb, 'Conseil du spécialiste : Une question difficile sur la transfusion en urgence. Il est recommandé de transfuser un culot O+ (0- chez une femme en âge de procréer) s''il ''agit d''une urgence vitale en absence de connaissance du groupe du donneur. En cas de possession d''une carte de donneur ou d''un dossier transfu sans doute sur l''identité, on peut transfuser un culot compatible (sans oublier le test ultime au lit du malade).', '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2687, 8, 'Traumatologie', 'Généralités sur les fractures de l’adulte', 'Monsieur V, 37 ans, est amené par le SAMU pour trauma suite à une chute d''escalade. Il a dévalé 15 mètres de falaise avant que son baudrier ne le retienne et a fini sa chute en s''écrasant contre la paroi. Il était casqué au moment de l''examen et n''aurait pas perdu connaissance. Son état s''est rapidement aggravé dans l''ambulance. À l''arrivée aux urgences, le patient parle de manière inappropriée, ses yeux s''ouvrent quand vous lui parlez. Il repousse votre main avec son bras gauche quand vous lui pincez le bras droit. Le patient est pâle et marbré aux membres inférieurs. Sa tension artérielle est à 89176 mmHg et sa fréquence cardiaque est à 112 bpm, sa saturation est à 80 %. Il semble être douloureux à la palpation abdominale et au niveau des côtes. Sa cuisse droite et sa jambe gauche sont déformées. Le sondage ramène une hématurie.', false, true, 'Quelles sont les autres thérapeutiques à entreprendre pour la prise en charge de ce patient ?', '[{"l":"A","t":"Remplissage par cristalloïdes 500 ml/30 min","c":true},{"l":"B","t":"Intubation orotrachéale si acidose aux gaz du sang","c":true},{"l":"C","t":"Vasopresseur type noradrénaline","c":true},{"l":"D","t":"Vasopresseur type dopamine","c":false},{"l":"E","t":"Corticoïdes","c":false}]'::jsonb, NULL, '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2688, 26, 'Traumatologie', 'Traumatisme du bassin : fracture, luxation traumatique de la hanche', 'Monsieur V, 37 ans, est amené par le SAMU pour trauma suite à une chute d''escalade. Il a dévalé 15 mètres de falaise avant que son baudrier ne le retienne et a fini sa chute en s''écrasant contre la paroi. Il était casqué au moment de l''examen et n''aurait pas perdu connaissance. Son état s''est rapidement aggravé dans l''ambulance. À l''arrivée aux urgences, le patient parle de manière inappropriée, ses yeux s''ouvrent quand vous lui parlez. Il repousse votre main avec son bras gauche quand vous lui pincez le bras droit. Le patient est pâle et marbré aux membres inférieurs. Sa tension artérielle est à 89176 mmHg et sa fréquence cardiaque est à 112 bpm, sa saturation est à 80 %. Il semble être douloureux à la palpation abdominale et au niveau des côtes. Sa cuisse droite et sa jambe gauche sont déformées. Le sondage ramène une hématurie.', false, true, 'Quel est le traitement de la fracture du fémur droit, du tibia gauche et du bassin ?', '[{"l":"A","t":"La fracture fémorale pourra être traitée par enclouage centromédullaire en cas de stabilisation hémodynamique","c":true},{"l":"B","t":"La fracture tibiale pourra être traitée par ostéosynthèse à foyer fermé en cas de stabilisation hémodynamique","c":true},{"l":"C","t":"La fracture du bassin pourra être traitée par fixateur externe","c":true},{"l":"D","t":"La prise en charge nécessite un plateau médicotechnique de radiologie interventionnelle","c":true},{"l":"E","t":"Une embolisation doit être réalisée sans attendre par guidage scannographique","c":false}]'::jsonb, NULL, '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2689, 8, 'Traumatologie', 'Généralités sur les fractures de l’adulte', 'Monsieur V, 37 ans, est amené par le SAMU pour trauma suite à une chute d''escalade. Il a dévalé 15 mètres de falaise avant que son baudrier ne le retienne et a fini sa chute en s''écrasant contre la paroi. Il était casqué au moment de l''examen et n''aurait pas perdu connaissance. Son état s''est rapidement aggravé dans l''ambulance. À l''arrivée aux urgences, le patient parle de manière inappropriée, ses yeux s''ouvrent quand vous lui parlez. Il repousse votre main avec son bras gauche quand vous lui pincez le bras droit. Le patient est pâle et marbré aux membres inférieurs. Sa tension artérielle est à 89176 mmHg et sa fréquence cardiaque est à 112 bpm, sa saturation est à 80 %. Il semble être douloureux à la palpation abdominale et au niveau des côtes. Sa cuisse droite et sa jambe gauche sont déformées. Le sondage ramène une hématurie.', false, true, 'À propos des fractures de côtes chez ce patient ?', '[{"l":"A","t":"Un traitement antalgique suffit en absence de complication","c":true},{"l":"B","t":"Un traitement chirurgical par ostéosynthèse est nécessaire en cas de fracture du sternum associée","c":true},{"l":"C","t":"Vous auriez pu évoquer une lésion hépatique chez ce patient","c":true},{"l":"D","t":"L''intérêt de la radiographie thoracique dans les fractures de côtes est la localisation précise de la fracture","c":false},{"l":"E","t":"Un volet costal correspond à la présence d''un trait de fracture sur 3 côtes consécutives","c":false}]'::jsonb, NULL, '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2690, 8, 'Traumatologie', 'Généralités sur les fractures de l’adulte', 'Monsieur V, 37 ans, est amené par le SAMU pour trauma suite à une chute d''escalade. Il a dévalé 15 mètres de falaise avant que son baudrier ne le retienne et a fini sa chute en s''écrasant contre la paroi. Il était casqué au moment de l''examen et n''aurait pas perdu connaissance. Son état s''est rapidement aggravé dans l''ambulance. À l''arrivée aux urgences, le patient parle de manière inappropriée, ses yeux s''ouvrent quand vous lui parlez. Il repousse votre main avec son bras gauche quand vous lui pincez le bras droit. Le patient est pâle et marbré aux membres inférieurs. Sa tension artérielle est à 89176 mmHg et sa fréquence cardiaque est à 112 bpm, sa saturation est à 80 %. Il semble être douloureux à la palpation abdominale et au niveau des côtes. Sa cuisse droite et sa jambe gauche sont déformées. Le sondage ramène une hématurie.', false, true, 'Après la prise en charge multidisciplinaire du patient, son état hémodynamique s''est stabilisé, le patient est Glasgow 15, il a été extubé, son hémoglobine est à 9 g/ dl. 48 h s''écoulent et le patient se dégrade brutalement. Il présente une détresse respiratoire aiguë, un purpura cutanée-muqueux, notamment au niveau des conjonctives, une confusion puis un coma fébrile. La radiographie du thorax montre un syndrome alvéolaire diffus bilatéral. Le bilan sanguin est le suivant : • Leucocytes : 7 000/mm 3 Hb : 7 g/dl, Ht : 35 % Plaquettes : 60 000/mm 3, fibrinogène : 3 g/I. • D-dimères : 600 ng/ml, TP : 70 %. Quelle est votre hypothèse diagnostique principale ?', '[{"l":"A","t":"Embolie pulmonaire","c":false},{"l":"B","t":"CIVD","c":false},{"l":"C","t":"Syndrome des emboles de cholestérol","c":false},{"l":"D","t":"Syndrome d''embolie graisseuse","c":true},{"l":"E","t":"Pneumopathie d''inhalation","c":false}]'::jsonb, 'Conseil du spécialiste : Syndrome d''embolie graisseuse= triade symptomatique (neuro/pneumo/cutanéo-muqueux) / bio = thrombopénie, anémie hémolytique (pas de diminution du fibrinogène ou du TP).', '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2691, 43, 'Traumatologie', 'Syndrome des loges', 'Monsieur V, 37 ans, est amené par le SAMU pour trauma suite à une chute d''escalade. Il a dévalé 15 mètres de falaise avant que son baudrier ne le retienne et a fini sa chute en s''écrasant contre la paroi. Il était casqué au moment de l''examen et n''aurait pas perdu connaissance. Son état s''est rapidement aggravé dans l''ambulance. À l''arrivée aux urgences, le patient parle de manière inappropriée, ses yeux s''ouvrent quand vous lui parlez. Il repousse votre main avec son bras gauche quand vous lui pincez le bras droit. Le patient est pâle et marbré aux membres inférieurs. Sa tension artérielle est à 89176 mmHg et sa fréquence cardiaque est à 112 bpm, sa saturation est à 80 %. Il semble être douloureux à la palpation abdominale et au niveau des côtes. Sa cuisse droite et sa jambe gauche sont déformées. Le sondage ramène une hématurie.', false, true, 'Finalement vous traitez le patient de manière symptomatique et son état pulmonaire et neurologique s''améliore. En l''examinant un matin, alors qu''il est toujours en soins intensifs vous évoquez un syndrome des loges typique de la jambe gauche, non résolutif après retrait du plâtre. Devant quels éléments cliniques évoquez-vous ce diagnostic?', '[{"l":"A","t":"Douleur résistante à la morphine","c":true},{"l":"B","t":"Abolition du pouls pédieux","c":false},{"l":"C","t":"Abolition du pouls tibial postérieur","c":false},{"l":"D","t":"Paresthésies de la première commissure du pied","c":true},{"l":"E","t":"Signe de Homans","c":false}]'::jsonb, NULL, '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2692, 42, 'Traumatologie', 'Fracture de jambe ouverte et fermée', 'Monsieur V, 37 ans, est amené par le SAMU pour trauma suite à une chute d''escalade. Il a dévalé 15 mètres de falaise avant que son baudrier ne le retienne et a fini sa chute en s''écrasant contre la paroi. Il était casqué au moment de l''examen et n''aurait pas perdu connaissance. Son état s''est rapidement aggravé dans l''ambulance. À l''arrivée aux urgences, le patient parle de manière inappropriée, ses yeux s''ouvrent quand vous lui parlez. Il repousse votre main avec son bras gauche quand vous lui pincez le bras droit. Le patient est pâle et marbré aux membres inférieurs. Sa tension artérielle est à 89176 mmHg et sa fréquence cardiaque est à 112 bpm, sa saturation est à 80 %. Il semble être douloureux à la palpation abdominale et au niveau des côtes. Sa cuisse droite et sa jambe gauche sont déformées. Le sondage ramène une hématurie.', false, true, 'Quels sont les facteurs de risque de syndrome des loges ?', '[{"l":"A","t":"Ostéosynthèse à foyer fermé","c":true},{"l":"B","t":"Fracture déplacée","c":true},{"l":"C","t":"Brûlure du 3e degré","c":true},{"l":"D","t":"Hématome compressif","c":true},{"l":"E","t":"Patient jeune","c":true}]'::jsonb, NULL, '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2693, 43, 'Traumatologie', 'Syndrome des loges', 'Monsieur V, 37 ans, est amené par le SAMU pour trauma suite à une chute d''escalade. Il a dévalé 15 mètres de falaise avant que son baudrier ne le retienne et a fini sa chute en s''écrasant contre la paroi. Il était casqué au moment de l''examen et n''aurait pas perdu connaissance. Son état s''est rapidement aggravé dans l''ambulance. À l''arrivée aux urgences, le patient parle de manière inappropriée, ses yeux s''ouvrent quand vous lui parlez. Il repousse votre main avec son bras gauche quand vous lui pincez le bras droit. Le patient est pâle et marbré aux membres inférieurs. Sa tension artérielle est à 89176 mmHg et sa fréquence cardiaque est à 112 bpm, sa saturation est à 80 %. Il semble être douloureux à la palpation abdominale et au niveau des côtes. Sa cuisse droite et sa jambe gauche sont déformées. Le sondage ramène une hématurie.', false, true, 'À propos de l''anatomie des loges de la jambe, quelles sont les propositions vraies ?', '[{"l":"A","t":"Il y a 3 loges dans la jambe","c":false},{"l":"B","t":"La loge postérieure superficielle comprend le muscle soléaire","c":true},{"l":"C","t":"La loge externe comprend le muscle long fibulaire","c":true},{"l":"D","t":"La loge interne comprend le long fléchisseur de l''hallux","c":false},{"l":"E","t":"La loge postérieure profonde comprend l''artère fibulaire","c":true}]'::jsonb, NULL, '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2694, 43, 'Traumatologie', 'Syndrome des loges', 'Monsieur V, 37 ans, est amené par le SAMU pour trauma suite à une chute d''escalade. Il a dévalé 15 mètres de falaise avant que son baudrier ne le retienne et a fini sa chute en s''écrasant contre la paroi. Il était casqué au moment de l''examen et n''aurait pas perdu connaissance. Son état s''est rapidement aggravé dans l''ambulance. À l''arrivée aux urgences, le patient parle de manière inappropriée, ses yeux s''ouvrent quand vous lui parlez. Il repousse votre main avec son bras gauche quand vous lui pincez le bras droit. Le patient est pâle et marbré aux membres inférieurs. Sa tension artérielle est à 89176 mmHg et sa fréquence cardiaque est à 112 bpm, sa saturation est à 80 %. Il semble être douloureux à la palpation abdominale et au niveau des côtes. Sa cuisse droite et sa jambe gauche sont déformées. Le sondage ramène une hématurie.', false, true, 'Quelle est votre prise en charge ?', '[{"l":"A","t":"Confirmation du diagnostic par mesure per-cutanée de la pression intra-musculaire","c":false},{"l":"B","t":"Apronévrotomie de décharge en urgence","c":true},{"l":"C","t":"Surjet d''attente","c":true},{"l":"D","t":"Fermeture cutanée progressive sur plusieurs jours","c":true},{"l":"E","t":"Information du patient du risque de séquelle neurologique","c":true}]'::jsonb, NULL, '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2695, 43, 'Traumatologie', 'Syndrome des loges', 'Monsieur V, 37 ans, est amené par le SAMU pour trauma suite à une chute d''escalade. Il a dévalé 15 mètres de falaise avant que son baudrier ne le retienne et a fini sa chute en s''écrasant contre la paroi. Il était casqué au moment de l''examen et n''aurait pas perdu connaissance. Son état s''est rapidement aggravé dans l''ambulance. À l''arrivée aux urgences, le patient parle de manière inappropriée, ses yeux s''ouvrent quand vous lui parlez. Il repousse votre main avec son bras gauche quand vous lui pincez le bras droit. Le patient est pâle et marbré aux membres inférieurs. Sa tension artérielle est à 89176 mmHg et sa fréquence cardiaque est à 112 bpm, sa saturation est à 80 %. Il semble être douloureux à la palpation abdominale et au niveau des côtes. Sa cuisse droite et sa jambe gauche sont déformées. Le sondage ramène une hématurie.', false, true, 'Concernant la physiopathologie de cette affection, quelles sont les propositions vraies ?', '[{"l":"A","t":"Elle est liée à une augmentation du volume dans un espace inextensible","c":true},{"l":"B","t":"La compression des artères de jambe est le phénomène le plus précoce","c":false},{"l":"C","t":"La diminution du retour veineux n''intervient pas dans le phénomène","c":false},{"l":"D","t":"L''œdème musculaire aggrave la surpression","c":true},{"l":"E","t":"La nécrose ischémique survient généralement après 6 heures","c":true}]'::jsonb, NULL, '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2696, 34, 'Rhumatologie', 'Lombalgies et lombosciatalgies', 'Monsieur D., 36 ans, consulte pour des douleurs lombaires apparues brutalement suite à un effort, en portant un canapé lors de son déménagement il y a 2jours. Ce patient professeur de tennis sans antécédent notable décrit une douleur lombaire majorée à la toux et à l''effort. Votre examen retrouve une contracture para-vertébrale lombaire et une douleur à la palpation des épineuses. La distance mainsol est légèrement augmentée, vous ne retrouvez pas de signe de Lasègue ou de Léri. Votre examen neurologique est normal. Le reste de l''examen est sans particularité.', false, true, 'L''indice de Schober est anormal chez ce patient, quelles sont les propositions vraies concernant ce test ?', '[{"l":"A","t":"Il permet d''objectiver la raideur du rachis dorsal","c":false},{"l":"B","t":"Il se mesure le patient penché en avant","c":true},{"l":"C","t":"Nécessite un repérage de la vertèbre L1","c":false},{"l":"D","t":"Nécessite un repère passant par la ligne des épineuses et la ligne bi-iliaque","c":true},{"l":"E","t":"Est inférieur à 10 cm chez le patient","c":false}]'::jsonb, NULL, '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2697, 9, 'Rhumatologie', 'Spondylarthrites', 'Monsieur D., 36 ans, consulte pour des douleurs lombaires apparues brutalement suite à un effort, en portant un canapé lors de son déménagement il y a 2jours. Ce patient professeur de tennis sans antécédent notable décrit une douleur lombaire majorée à la toux et à l''effort. Votre examen retrouve une contracture para-vertébrale lombaire et une douleur à la palpation des épineuses. La distance mainsol est légèrement augmentée, vous ne retrouvez pas de signe de Lasègue ou de Léri. Votre examen neurologique est normal. Le reste de l''examen est sans particularité.', false, true, 'Quel est votre diagnostic ?', '[{"l":"A","t":"Lombalgie commune aiguë","c":true},{"l":"B","t":"Lumbago","c":true},{"l":"C","t":"Lombalgie symptomatique aiguë","c":false},{"l":"D","t":"Lombosciatique","c":false},{"l":"E","t":"Spondylarthropathie","c":false}]'::jsonb, NULL, '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2698, 34, 'Rhumatologie', 'Lombalgies et lombosciatalgies', 'Monsieur D., 36 ans, consulte pour des douleurs lombaires apparues brutalement suite à un effort, en portant un canapé lors de son déménagement il y a 2jours. Ce patient professeur de tennis sans antécédent notable décrit une douleur lombaire majorée à la toux et à l''effort. Votre examen retrouve une contracture para-vertébrale lombaire et une douleur à la palpation des épineuses. La distance mainsol est légèrement augmentée, vous ne retrouvez pas de signe de Lasègue ou de Léri. Votre examen neurologique est normal. Le reste de l''examen est sans particularité.', false, true, 'Quelle est l''hypothèse étiologique la plus probable ?', '[{"l":"A","t":"Canal lombaire étroit","c":false},{"l":"B","t":"Discarthrose","c":false},{"l":"C","t":"Spondylarthrose","c":false},{"l":"D","t":"Conflit disco-radiculaire","c":false},{"l":"E","t":"Hernie discale","c":true}]'::jsonb, 'Conseil du spécialiste : La hernie discale est plus fréquente chez le jeune, l''absence de Léri et de Laségue est en faveur de l''absence de conflit disco-radiculaire', '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2699, 34, 'Rhumatologie', 'Lombalgies et lombosciatalgies', 'Monsieur D., 36 ans, consulte pour des douleurs lombaires apparues brutalement suite à un effort, en portant un canapé lors de son déménagement il y a 2jours. Ce patient professeur de tennis sans antécédent notable décrit une douleur lombaire majorée à la toux et à l''effort. Votre examen retrouve une contracture para-vertébrale lombaire et une douleur à la palpation des épineuses. La distance mainsol est légèrement augmentée, vous ne retrouvez pas de signe de Lasègue ou de Léri. Votre examen neurologique est normal. Le reste de l''examen est sans particularité.', false, true, 'Quel est votre bilan paraclinique ?', '[{"l":"A","t":"Radiographies du rachis lombaire de face","c":false},{"l":"B","t":"Radiographies du rachis lombaire de profil","c":false},{"l":"C","t":"TOM du rachis lombaire","c":false},{"l":"D","t":"IRM du rachis lombaire","c":false},{"l":"E","t":"Aucun examen complémentaire ne doit être prescrit","c":true}]'::jsonb, 'Conseil du spécialiste : Pas d''examen complémentaire devant un Lumbago de moins de 7 semaines d''allure bénigne.', '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2700, 34, 'Rhumatologie', 'Lombalgies et lombosciatalgies', 'Monsieur D., 36 ans, consulte pour des douleurs lombaires apparues brutalement suite à un effort, en portant un canapé lors de son déménagement il y a 2jours. Ce patient professeur de tennis sans antécédent notable décrit une douleur lombaire majorée à la toux et à l''effort. Votre examen retrouve une contracture para-vertébrale lombaire et une douleur à la palpation des épineuses. La distance mainsol est légèrement augmentée, vous ne retrouvez pas de signe de Lasègue ou de Léri. Votre examen neurologique est normal. Le reste de l''examen est sans particularité.', false, true, 'Quelle est votre prise en charge ?', '[{"l":"A","t":"Repos strict au lit","c":false},{"l":"B","t":"Arrêt de travail pendant plusieurs semaines","c":false},{"l":"C","t":"Apprentissage du verrouillage lombaire","c":true},{"l":"D","t":"Bi-profénid 1OO mg, 2 comprimés par jour avec co-préscription d''inhibiteur de la pompe à proton","c":false},{"l":"E","t":"Corset lombaire","c":true}]'::jsonb, NULL, '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2701, 34, 'Rhumatologie', 'Lombalgies et lombosciatalgies', 'Monsieur D., 36 ans, consulte pour des douleurs lombaires apparues brutalement suite à un effort, en portant un canapé lors de son déménagement il y a 2jours. Ce patient professeur de tennis sans antécédent notable décrit une douleur lombaire majorée à la toux et à l''effort. Votre examen retrouve une contracture para-vertébrale lombaire et une douleur à la palpation des épineuses. La distance mainsol est légèrement augmentée, vous ne retrouvez pas de signe de Lasègue ou de Léri. Votre examen neurologique est normal. Le reste de l''examen est sans particularité.', false, true, 'Monsieur D. a respecté vos recommandations mais ses douleurs sont devenues chroniques et récidivantes. 2 ans plus tard, le patient consulte très anxieux aux urgences car ses douleurs se sont aggravées depuis quelques jours et irradient maintenant dans le membre inférieur droit. En l''examinant, vous faites le diagnostic de lombosciatique LS droite. Quels éléments cliniques vous ont orienté vers ce diagnostic?', '[{"l":"A","t":"Un signe de la sonnette","c":true},{"l":"B","t":"Un signe de Léri positif à droite","c":false},{"l":"C","t":"Une douleur allant de la face externe de la jambe jusqu''au dos du pied et de l''hallux","c":false},{"l":"D","t":"Un réflexe achilléen droit vif et polycinétique","c":true},{"l":"E","t":"Une difficulté à la marche sur les talons","c":true}]'::jsonb, 'Conseil du spécialiste : Laségue = sciatique I Léri = cruralgie', '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2702, 34, 'Rhumatologie', 'Lombalgies et lombosciatalgies', 'Monsieur D., 36 ans, consulte pour des douleurs lombaires apparues brutalement suite à un effort, en portant un canapé lors de son déménagement il y a 2jours. Ce patient professeur de tennis sans antécédent notable décrit une douleur lombaire majorée à la toux et à l''effort. Votre examen retrouve une contracture para-vertébrale lombaire et une douleur à la palpation des épineuses. La distance mainsol est légèrement augmentée, vous ne retrouvez pas de signe de Lasègue ou de Léri. Votre examen neurologique est normal. Le reste de l''examen est sans particularité.', false, true, 'Quels signes cliniques imposent une prise en charge en urgence de cette lombosciatique ?', '[{"l":"A","t":"Une atonie sphinctérienne au toucher rectal","c":true},{"l":"B","t":"Un globe vésical","c":true},{"l":"C","t":"Un déficit moteur progressif","c":true},{"l":"D","t":"Une capacité à lutter contre la pesanteur mais pas contre la flexion plantaire forcée.","c":false},{"l":"E","t":"Un signe de Babinski droit","c":false}]'::jsonb, 'Conseil du spécialiste : Déficit moteur >3/5 ou progressif= signe de gravité 1O. Infiltration épidurales', '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2703, 34, 'Rhumatologie', 'Lombalgies et lombosciatalgies', 'Monsieur D., 36 ans, consulte pour des douleurs lombaires apparues brutalement suite à un effort, en portant un canapé lors de son déménagement il y a 2jours. Ce patient professeur de tennis sans antécédent notable décrit une douleur lombaire majorée à la toux et à l''effort. Votre examen retrouve une contracture para-vertébrale lombaire et une douleur à la palpation des épineuses. La distance mainsol est légèrement augmentée, vous ne retrouvez pas de signe de Lasègue ou de Léri. Votre examen neurologique est normal. Le reste de l''examen est sans particularité.', false, true, 'Quel examen doit alors être réalisé en urgence si un de ces signes est présent ?', '[{"l":"A","t":"Radiographies du rachis lombaire de face et de profil","c":false},{"l":"B","t":"TOM du rachis lombaire et de la charnière lombo-sacrée","c":false},{"l":"C","t":"IRM médullaire","c":true},{"l":"D","t":"Sacco-radiculographie en position debout","c":false},{"l":"E","t":"Aucune de ces réponses","c":false}]'::jsonb, NULL, '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2704, 34, 'Rhumatologie', 'Lombalgies et lombosciatalgies', 'Monsieur D., 36 ans, consulte pour des douleurs lombaires apparues brutalement suite à un effort, en portant un canapé lors de son déménagement il y a 2jours. Ce patient professeur de tennis sans antécédent notable décrit une douleur lombaire majorée à la toux et à l''effort. Votre examen retrouve une contracture para-vertébrale lombaire et une douleur à la palpation des épineuses. La distance mainsol est légèrement augmentée, vous ne retrouvez pas de signe de Lasègue ou de Léri. Votre examen neurologique est normal. Le reste de l''examen est sans particularité.', false, true, 'Finalement cet épisode de sciatique ne présente pas de signe de gravité. Quelle est votre prise en charge ?', '[{"l":"A","t":"Prescription d''antalgiques de palier 1et Il et de myorelaxants","c":true},{"l":"B","t":"Prescription de corticothérapie systémique de courte durée","c":false},{"l":"C","t":"Manipulations rachidiennes","c":false},{"l":"D","t":"Infiltrations intra-durales en cas d''échec des antalgiques per os","c":false},{"l":"E","t":"Arrêt de travail","c":true}]'::jsonb, NULL, '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2705, 34, 'Rhumatologie', 'Lombalgies et lombosciatalgies', 'Monsieur D., 36 ans, consulte pour des douleurs lombaires apparues brutalement suite à un effort, en portant un canapé lors de son déménagement il y a 2jours. Ce patient professeur de tennis sans antécédent notable décrit une douleur lombaire majorée à la toux et à l''effort. Votre examen retrouve une contracture para-vertébrale lombaire et une douleur à la palpation des épineuses. La distance mainsol est légèrement augmentée, vous ne retrouvez pas de signe de Lasègue ou de Léri. Votre examen neurologique est normal. Le reste de l''examen est sans particularité.', false, true, 'À propos de la chirurgie chez ce patient, quelles sont les propositions vraies ?', '[{"l":"A","t":"Elle est adaptée car la corrélation clinico-radiologique est bonne","c":true},{"l":"B","t":"Le traitement est une laminectomie avec discectomie","c":true},{"l":"C","t":"Une nucléotomie laser est possible chez ce patient","c":true},{"l":"D","t":"La chirurgie n''est pas indiquée","c":false},{"l":"E","t":"La chirurgie n''aura pas d''effet sur les douleurs lombaires","c":true}]'::jsonb, 'Conseil du spécialiste : Attention la chirurgie a un effet sur les radiculalgies mais les lombalgies persistent.', '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2706, 34, 'Rhumatologie', 'Lombalgies et lombosciatalgies', 'Monsieur D., 36 ans, consulte pour des douleurs lombaires apparues brutalement suite à un effort, en portant un canapé lors de son déménagement il y a 2jours. Ce patient professeur de tennis sans antécédent notable décrit une douleur lombaire majorée à la toux et à l''effort. Votre examen retrouve une contracture para-vertébrale lombaire et une douleur à la palpation des épineuses. La distance mainsol est légèrement augmentée, vous ne retrouvez pas de signe de Lasègue ou de Léri. Votre examen neurologique est normal. Le reste de l''examen est sans particularité.', false, true, 'Vous opérez ce patient à ciel ouvert et l''opération se passe bien. En salle de réveil, vous faites un rapide examen neurologique et vous retrouvez une paralysie complète des deux membres inférieurs et un syndrome de la queue-de-cheval. Quelle est votre hypothèse diagnostique principale ?', '[{"l":"A","t":"Infection du site opératoire","c":false},{"l":"B","t":"Hématome compressif lombaire","c":true},{"l":"C","t":"Décompensation de discopathie lombaire","c":false},{"l":"D","t":"Fistule durale","c":false},{"l":"E","t":"Fracture rachidienne","c":false}]'::jsonb, NULL, '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2707, 34, 'Rhumatologie', 'Lombalgies et lombosciatalgies', 'Monsieur D., 36 ans, consulte pour des douleurs lombaires apparues brutalement suite à un effort, en portant un canapé lors de son déménagement il y a 2jours. Ce patient professeur de tennis sans antécédent notable décrit une douleur lombaire majorée à la toux et à l''effort. Votre examen retrouve une contracture para-vertébrale lombaire et une douleur à la palpation des épineuses. La distance mainsol est légèrement augmentée, vous ne retrouvez pas de signe de Lasègue ou de Léri. Votre examen neurologique est normal. Le reste de l''examen est sans particularité.', false, true, 'Vous expliquez au patient la possibilité d''un aléa thérapeutique, expliquez ce terme :', '[{"l":"A","t":"Il concerne un risque qui ne peux être maîtrisé","c":true},{"l":"B","t":"Il concerne un acte de prévention, de diagnostic ou de soins","c":true},{"l":"C","t":"Il ne concerne pas les infections nosocomiales","c":false},{"l":"D","t":"Il concerne tout acte médical à l''hôpital public même si le dommage est dû à une faute","c":false},{"l":"E","t":"Il concerne les accidents médicaux","c":true}]'::jsonb, NULL, '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2708, 34, 'Rhumatologie', 'Lombalgies et lombosciatalgies', 'Monsieur D., 36 ans, consulte pour des douleurs lombaires apparues brutalement suite à un effort, en portant un canapé lors de son déménagement il y a 2jours. Ce patient professeur de tennis sans antécédent notable décrit une douleur lombaire majorée à la toux et à l''effort. Votre examen retrouve une contracture para-vertébrale lombaire et une douleur à la palpation des épineuses. La distance mainsol est légèrement augmentée, vous ne retrouvez pas de signe de Lasègue ou de Léri. Votre examen neurologique est normal. Le reste de l''examen est sans particularité.', false, true, 'À propos des indemnisations possibles s''il s''agit d''un aléa thérapeutique :', '[{"l":"A","t":"Le patient sera indemnisé au titre de la solidarité nationale","c":true},{"l":"B","t":"Le patient peut s''adresser à la CRCI aux fins de déterminer son préjudice","c":true},{"l":"C","t":"Une indemnisation est possible quelle que soit l''importance du préjudice","c":false},{"l":"D","t":"L''indemnisation est possible par l''assureur du médecin","c":false},{"l":"E","t":"C''est l''ONIAM qui est chargé de présenter une offre d''indemnisation à la victime","c":true}]'::jsonb, 'Conseil du spécialiste : Une indemnisation est possible pour un taux d''IPP > 25 % ou une ITT > 6 mois', '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2709, 31, 'Traumatologie', 'Fracture du fémur proximal (col du fémur et massif trochantérien)', 'Vous recevez un dimanche aux urgences Monsieur P, 32 ans, qui consulte pour impotence fonctionnelle totale suite à un mauvais tacle lors d''un match de football survenu il y''a 30 minutes. La cheville gauche du patient est tuméfiée. Ce patient sportif n''a aucun antécédent médico-chirurgical.', false, true, 'Quels sont les signes cliniques qui vous feraient évoquer une rupture du tendon d''Achille ?', '[{"l":"A","t":"Une douleur survenue lors d''une décélération brutale","c":false},{"l":"B","t":"Une positivité du signe de Thompson","c":true},{"l":"C","t":"Une perte de l''équinisme physiologique du pied en décubitus ventral","c":true},{"l":"D","t":"Un hématome plantaire","c":false},{"l":"E","t":"Un déficit à la flexion dorsale du pied","c":false}]'::jsonb, NULL, '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2710, 39, 'Traumatologie', 'Fracture du cou-de-pied : fracture malléolaire, fracture du pilon tibial', 'Vous recevez un dimanche aux urgences Monsieur P, 32 ans, qui consulte pour impotence fonctionnelle totale suite à un mauvais tacle lors d''un match de football survenu il y''a 30 minutes. La cheville gauche du patient est tuméfiée. Ce patient sportif n''a aucun antécédent médico-chirurgical.', false, true, 'Vous ne retrouvez pas ces signes cliniques mais le patient est très douloureux. Quelle est votre conduite antalgique ?', '[{"l":"A","t":"Association d''un palier 1et d''une pallier Il si douleur > 30 / 100","c":true},{"l":"B","t":"Attelle amovible","c":true},{"l":"C","t":"Titration morphinique si EVA > 30/1OO","c":false},{"l":"D","t":"Association d''un antalgique palier 11 et d''un palier 111 en cas d''échec de la morphine","c":false},{"l":"E","t":"Prescription de dextropropoxyphène (palier Il) en pre-mière intention si EVA > 30/100","c":false}]'::jsonb, NULL, '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2711, 39, 'Traumatologie', 'Fracture du cou-de-pied : fracture malléolaire, fracture du pilon tibial', 'Vous recevez un dimanche aux urgences Monsieur P, 32 ans, qui consulte pour impotence fonctionnelle totale suite à un mauvais tacle lors d''un match de football survenu il y''a 30 minutes. La cheville gauche du patient est tuméfiée. Ce patient sportif n''a aucun antécédent médico-chirurgical.', false, true, 'Quelles complications devez-vous rechercher spécifiquement si vous suspectez une fracture malléolaire ?', '[{"l":"A","t":"Phlyctènes malléolaires","c":true},{"l":"B","t":"Déficit des releveurs des orteils","c":true},{"l":"C","t":"Non-palpation du pouls fibulaire","c":false},{"l":"D","t":"Douleur à la palpation de la tête fibulaire","c":true},{"l":"E","t":"Ouverture cutanée malléolaire","c":true}]'::jsonb, 'Conseil du spécialiste : Penser à la fracture de Maisonneuve (atteinte du sciatique poplité ex-terne)', '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2712, 39, 'Traumatologie', 'Fracture du cou-de-pied : fracture malléolaire, fracture du pilon tibial', 'Vous recevez un dimanche aux urgences Monsieur P, 32 ans, qui consulte pour impotence fonctionnelle totale suite à un mauvais tacle lors d''un match de football survenu il y''a 30 minutes. La cheville gauche du patient est tuméfiée. Ce patient sportif n''a aucun antécédent médico-chirurgical.', false, true, 'Quels sont les critères d''Ottawa qui amèneraient à la prescription d''une radiographie dans l''entorse de cheville?', '[{"l":"A","t":"Âge > 50 ans","c":false},{"l":"B","t":"Impossibilité de faire 4 pas à distance du trauma","c":false},{"l":"C","t":"Sensibilité à la palpation du naviculaire","c":true},{"l":"D","t":"Sensibilité à la palpation de la base du 5e métatarsien","c":true},{"l":"E","t":"Sensibilité à la palpation de la malléole","c":true}]'::jsonb, NULL, '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2713, 39, 'Traumatologie', 'Fracture du cou-de-pied : fracture malléolaire, fracture du pilon tibial', 'Vous recevez un dimanche aux urgences Monsieur P, 32 ans, qui consulte pour impotence fonctionnelle totale suite à un mauvais tacle lors d''un match de football survenu il y''a 30 minutes. La cheville gauche du patient est tuméfiée. Ce patient sportif n''a aucun antécédent médico-chirurgical.', false, true, 'Vous mettez en évidence une souffrance cutanée, quelle est alors votre prise en charge au SAU ?', '[{"l":"A","t":"Mise en place d''une traction en urgence","c":false},{"l":"B","t":"Réduction sous contrôle de la scopie","c":false},{"l":"C","t":"Manœuvre de l''arrache-botte","c":true},{"l":"D","t":"Mise en place d''une immobilisation plâtrée après réduction","c":true},{"l":"E","t":"Réalisation de la radiographie en première intention","c":false}]'::jsonb, 'Conseil du spécialiste : Fracture sus-tuberculaire : au-dessus du ligament tibio-fibulaire, avant réduction il devait y avoir un diastasis tibio-fibulaire qui n''est plus visible sur ces radio. C''est la fracture inter-tuberculaire qui est la plus fréquente.', '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2714, 39, 'Traumatologie', 'Fracture du cou-de-pied : fracture malléolaire, fracture du pilon tibial', 'Vous recevez un dimanche aux urgences Monsieur P, 32 ans, qui consulte pour impotence fonctionnelle totale suite à un mauvais tacle lors d''un match de football survenu il y''a 30 minutes. La cheville gauche du patient est tuméfiée. Ce patient sportif n''a aucun antécédent médico-chirurgical.', false, true, 'Concernant le secret médical, quelles sont les propositions vraies ?', '[{"l":"A","t":"Le secret médical n''est pas opposable au proches dans le cas du patient","c":false},{"l":"B","t":"Si le médecin du travail de son entreprise appelle, vous pouvez lui répondre","c":false},{"l":"C","t":"Si la police appelle pour enquête, vous devez rompre le secret médical","c":false},{"l":"D","t":"Si le médecin de la mututelle du patient appelle, vous pouvez lui répondre","c":false},{"l":"E","t":"Aucune de ces réponses","c":true}]'::jsonb, NULL, '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2715, 39, 'Traumatologie', 'Fracture du cou-de-pied : fracture malléolaire, fracture du pilon tibial', 'Vous recevez un dimanche aux urgences Monsieur P, 32 ans, qui consulte pour impotence fonctionnelle totale suite à un mauvais tacle lors d''un match de football survenu il y''a 30 minutes. La cheville gauche du patient est tuméfiée. Ce patient sportif n''a aucun antécédent médico-chirurgical.', false, true, 'Quel sont les plans thérapeutiques qui vous paraissent adaptés chez ce patient sachant que la fracture est déplacée et que la peau reste en bon état ?', '[{"l":"A","t":"Ostéosynthèse par fixateur externe","c":false},{"l":"B","t":"Ostéosynthèse à foyer ouvert","c":true},{"l":"C","t":"Plâtre cruro-pédieux seul 6 semaines","c":false},{"l":"D","t":"Immobilisation par botte platrée 6 semaines en post-opératoire","c":true},{"l":"E","t":"Absence d''immobilisation en post-opératoire","c":false}]'::jsonb, 'Conseil du spécialiste : Genou en flexion d''au moins 10°.', '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2716, 37, 'Traumatologie', 'Traumatismes osseux du genou', 'Vous recevez un dimanche aux urgences Monsieur P, 32 ans, qui consulte pour impotence fonctionnelle totale suite à un mauvais tacle lors d''un match de football survenu il y''a 30 minutes. La cheville gauche du patient est tuméfiée. Ce patient sportif n''a aucun antécédent médico-chirurgical.', false, true, 'Quelles sont les modalités de confection d''un plâtre cruro-pédieux ?', '[{"l":"A","t":"Contention du bassin jusqu''au pied","c":false},{"l":"B","t":"Les orteils sont libres","c":true},{"l":"C","t":"La cheville est à 90°","c":true},{"l":"D","t":"Le genou est en extension","c":false},{"l":"E","t":"Le pied est en légère rotation externe","c":true}]'::jsonb, NULL, '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2717, 39, 'Traumatologie', 'Fracture du cou-de-pied : fracture malléolaire, fracture du pilon tibial', 'Vous recevez un dimanche aux urgences Monsieur P, 32 ans, qui consulte pour impotence fonctionnelle totale suite à un mauvais tacle lors d''un match de football survenu il y''a 30 minutes. La cheville gauche du patient est tuméfiée. Ce patient sportif n''a aucun antécédent médico-chirurgical.', false, true, 'Vous revoyez Monsieur P. à la consultation du deuxième jour, celui-ci se plaint de douleurs sous son plâtre. Quels diagnostics évoquez-vous ?', '[{"l":"A","t":"Thrombophlébite surale","c":true},{"l":"B","t":"Déplacement secondaire","c":true},{"l":"C","t":"Pseudarthrose","c":false},{"l":"D","t":"Syndrome compressif sous plâtre","c":true},{"l":"E","t":"Ostéo-arthrite","c":true}]'::jsonb, NULL, '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2718, 6, 'Traumatologie', 'Arthrose (hanche, genou)', 'Vous recevez un dimanche aux urgences Monsieur P, 32 ans, qui consulte pour impotence fonctionnelle totale suite à un mauvais tacle lors d''un match de football survenu il y''a 30 minutes. La cheville gauche du patient est tuméfiée. Ce patient sportif n''a aucun antécédent médico-chirurgical.', false, true, 'Le patient vous demande quelles sont les complications tardives de sa fracture : que lui dites-vous ?', '[{"l":"A","t":"Les enraidissements sont fréquents","c":true},{"l":"B","t":"Un cal vicieux est possible","c":true},{"l":"C","t":"Une arthrose tibio-calcanéenne est fréquente","c":false},{"l":"D","t":"Une pseudarthrose est possible","c":true},{"l":"E","t":"Une ostéonécroe aseptique est fréquente","c":false}]'::jsonb, NULL, '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2719, 39, 'Traumatologie', 'Fracture du cou-de-pied : fracture malléolaire, fracture du pilon tibial', 'Vous recevez un dimanche aux urgences Monsieur P, 32 ans, qui consulte pour impotence fonctionnelle totale suite à un mauvais tacle lors d''un match de football survenu il y''a 30 minutes. La cheville gauche du patient est tuméfiée. Ce patient sportif n''a aucun antécédent médico-chirurgical.', false, true, 'Quelles sont les modalités de prescription de la kinésthérapie?', '[{"l":"A","t":"Autorééducation","c":true},{"l":"B","t":"Mobilisation des orteils","c":true},{"l":"C","t":"Contraction du quadriceps","c":true},{"l":"D","t":"Contractions isométriques sous plâtre","c":true},{"l":"E","t":"Pas d''appui avant 6 semaines","c":true}]'::jsonb, NULL, '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2720, 39, 'Traumatologie', 'Fracture du cou-de-pied : fracture malléolaire, fracture du pilon tibial', 'Vous recevez un dimanche aux urgences Monsieur P, 32 ans, qui consulte pour impotence fonctionnelle totale suite à un mauvais tacle lors d''un match de football survenu il y''a 30 minutes. La cheville gauche du patient est tuméfiée. Ce patient sportif n''a aucun antécédent médico-chirurgical.', false, true, 'Quels sont les principes de l''éducation du patient concernant le plâtre ?', '[{"l":"A","t":"Ne pas mouiller le plâtre","c":true},{"l":"B","t":"Appui partiel autorisé sur le plâtre avec des béquilles uniquement","c":false},{"l":"C","t":"Contrôles systématiques réguliers en consultation","c":true},{"l":"D","t":"Prise de paracétamol en cas de douleurs du membre inférieur.","c":false},{"l":"E","t":"Arrêt de l''anticoagulation avec reprise de la kinésithérapie","c":false}]'::jsonb, 'Conseil du spécialiste : La radiographie est normale, on peut exclure l''arthrose et la pseudarthrose. Le matériel d''ostéosynthèse est en place. L''algodystrophie donne des troubles cutanés, il n''y a pas de raison que le patient présente une AOMI. ..', '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2721, 39, 'Traumatologie', 'Fracture du cou-de-pied : fracture malléolaire, fracture du pilon tibial', 'Vous recevez un dimanche aux urgences Monsieur P, 32 ans, qui consulte pour impotence fonctionnelle totale suite à un mauvais tacle lors d''un match de football survenu il y''a 30 minutes. La cheville gauche du patient est tuméfiée. Ce patient sportif n''a aucun antécédent médico-chirurgical.', false, true, 'Quel est le principe du traitement ?', '[{"l":"A","t":"Angioplastie","c":false},{"l":"B","t":"Antalgiques","c":true},{"l":"C","t":"Kinésithérapie","c":true},{"l":"D","t":"Chirurgie programmée pour ablation du matériel et nouvelle ostéosynthèse","c":false},{"l":"E","t":"Arthrodèse tibio-taienne","c":false}]'::jsonb, NULL, '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2722, 39, 'Traumatologie', 'Fracture du cou-de-pied : fracture malléolaire, fracture du pilon tibial', 'Vous recevez un dimanche aux urgences Monsieur P, 32 ans, qui consulte pour impotence fonctionnelle totale suite à un mauvais tacle lors d''un match de football survenu il y''a 30 minutes. La cheville gauche du patient est tuméfiée. Ce patient sportif n''a aucun antécédent médico-chirurgical.', false, true, 'Quels sont les principes de prescription de la kinésithérapie?', '[{"l":"A","t":"L''ordonnance doit comporter la mention kiné-balnéothérapie si cette technique est nécessaire","c":true},{"l":"B","t":"Il ne doit pas être mentionné au kinésithérapeute le diagnostic, dans le respect du secret médical.","c":false},{"l":"C","t":"Le nombre et la fréquence des séances doivent être absolument précisés pour éviter une « auto-prescription » du kinésithérapeute","c":false},{"l":"D","t":"La mention « à domicile » est nécessaire si le patient ne peut pas se déplacer au cabinet du kinésithérapeute","c":true},{"l":"E","t":"La mention « en urgence » est utile","c":true}]'::jsonb, NULL, '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2723, 8, 'Traumatologie', 'Généralités sur les fractures de l’adulte', 'Vous recevez aux urgences 3 jeunes de 28, 27 et 26 ans dans un contexte d''accident de la route survenu la nuit. La voiture a embouti un camion par l''arrière et a pris feu. Le conducteur est resté bloqué, incarcéré dans la voiture jusqu''à l''arrivée des pompiers. Le passager avant est décédé sur les lieux de /''accident. Le passager arrière a pu être extrait par le conducteur du camion qui a ensuite éteint le feu grâce à son extincteur de secours. À l''arrivée au SAU, le conducteur est glasgow 13. Il pré-sente de nombreuses brûlures au visage et sur le thorax qui lui font atrocement mal. Il se plaint de douleurs cervicales, de céphalées et de troubles visuels. La palpation de l''ensemble du cadre osseux est normale. Il vomit. Vous retrouvez des marbrures aux genoux. Vous remarquez la présence de suie dans les VADS. Ses constantes sont les suivantes : FC : 120 bpm; PA: 90110 ; Sp02: 97 %; FR: 16 /min. L''ECG révèle un trouble de la conduction ventriculaire non connu. Le passager arrière quant à lui est dans le coma et pré-sente une large plaie à la tête. Il est pris en charge par les réanimateurs.', false, true, 'Concernant votre examen clinique du conducteur :', '[{"l":"A","t":"Une asymétrie de la pression artérielle aux membres supérieurs vous fait évoquer une rupture de l''isthme aortique","c":true},{"l":"B","t":"Une asymétrie de la pression artérielle aux membres supérieurs vous fait évoquer une dissection aortique","c":true},{"l":"C","t":"Un emphysème sous-cutané cervical peut vous faire évoquer une rupture de l''axe trachéo-bronchique","c":true},{"l":"D","t":"Une rupture splénique peut passer inaperçue","c":true},{"l":"E","t":"Le port de la ceinture permet d''exclure des traumatismes thoraciques","c":false}]'::jsonb, NULL, '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2724, 24, 'Traumatologie', 'Traumatismes vertébraux-médullaires', 'Vous recevez aux urgences 3 jeunes de 28, 27 et 26 ans dans un contexte d''accident de la route survenu la nuit. La voiture a embouti un camion par l''arrière et a pris feu. Le conducteur est resté bloqué, incarcéré dans la voiture jusqu''à l''arrivée des pompiers. Le passager avant est décédé sur les lieux de /''accident. Le passager arrière a pu être extrait par le conducteur du camion qui a ensuite éteint le feu grâce à son extincteur de secours. À l''arrivée au SAU, le conducteur est glasgow 13. Il pré-sente de nombreuses brûlures au visage et sur le thorax qui lui font atrocement mal. Il se plaint de douleurs cervicales, de céphalées et de troubles visuels. La palpation de l''ensemble du cadre osseux est normale. Il vomit. Vous retrouvez des marbrures aux genoux. Vous remarquez la présence de suie dans les VADS. Ses constantes sont les suivantes : FC : 120 bpm; PA: 90110 ; Sp02: 97 %; FR: 16 /min. L''ECG révèle un trouble de la conduction ventriculaire non connu. Le passager arrière quant à lui est dans le coma et pré-sente une large plaie à la tête. Il est pris en charge par les réanimateurs.', false, true, 'Concernant votre examen clinique neurologique du conducteur :', '[{"l":"A","t":"Vous suspectez une lésion médullaire de niveau C4 en cas de troubles ventilatoires","c":true},{"l":"B","t":"Vous suspectez un syndrome de Bronwn Sequard droit en cas d''hémiplégie droite, déficit de la sensibilité thermo-algique droite et déficit de la sensibilité protopathique gauche","c":false},{"l":"C","t":"Un syndrome pyramidal des deux membres inférieurs avec anesthésie en selle peut vous faire évoquer un syndrome de la queue-de-cheval","c":false},{"l":"D","t":"Il existe un respect de la sensibilité au pique-touche en cas de syndrome de contusion antérieure de la moelle","c":false},{"l":"E","t":"Le score ASIA peut vous aider à suivre l''évolution neurologique du patient.","c":true}]'::jsonb, NULL, '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
(2725, 8, 'Traumatologie', 'Généralités sur les fractures de l’adulte', 'Vous recevez aux urgences 3 jeunes de 28, 27 et 26 ans dans un contexte d''accident de la route survenu la nuit. La voiture a embouti un camion par l''arrière et a pris feu. Le conducteur est resté bloqué, incarcéré dans la voiture jusqu''à l''arrivée des pompiers. Le passager avant est décédé sur les lieux de /''accident. Le passager arrière a pu être extrait par le conducteur du camion qui a ensuite éteint le feu grâce à son extincteur de secours. À l''arrivée au SAU, le conducteur est glasgow 13. Il pré-sente de nombreuses brûlures au visage et sur le thorax qui lui font atrocement mal. Il se plaint de douleurs cervicales, de céphalées et de troubles visuels. La palpation de l''ensemble du cadre osseux est normale. Il vomit. Vous retrouvez des marbrures aux genoux. Vous remarquez la présence de suie dans les VADS. Ses constantes sont les suivantes : FC : 120 bpm; PA: 90110 ; Sp02: 97 %; FR: 16 /min. L''ECG révèle un trouble de la conduction ventriculaire non connu. Le passager arrière quant à lui est dans le coma et pré-sente une large plaie à la tête. Il est pris en charge par les réanimateurs.', false, true, 'À propos de l''évaluation de la gravité des brûlures :', '[{"l":"A","t":"La présence de phlyctènes et la douleur intense vous évoquent des brûlures au second degré superficiel","c":true},{"l":"B","t":"Un score de BAUX permet d''évaluer la gravité des brûlures","c":true},{"l":"C","t":"Une des principales complications précoces des brûlures étendue est l''hyperthermie","c":false},{"l":"D","t":"Une des complications tardives est la dénutrition","c":true},{"l":"E","t":"La brûlure circonférentielle du bras est un signe de gravité","c":true}]'::jsonb, NULL, '["Médicilline – Cas cliniques en Orthopédie (Delpla 2015)"]'::jsonb),
